insert into public.questions
  (id, subject, topic, difficulty, text, options, correct_index, explanation, source, is_custom, created_at)
values
  ('eng-001', 'english-language', 'Grammar', 'easy', 'Choose the correct option: Neither the teacher nor the students ___ ready for the assembly.', '["is","are","was","has"]'::jsonb, 1, 'With ''neither...nor'', the verb agrees with the nearer subject, ''students'', so the plural verb ''are'' is correct.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('eng-002', 'english-language', 'Grammar', 'easy', 'She has been living in Enugu ___ 2015.', '["for","since","from","during"]'::jsonb, 1, '''Since'' is used with a specific point in time; ''for'' is used with a length of time.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('eng-003', 'english-language', 'Grammar', 'medium', 'If I ___ you, I would apologise to the principal immediately.', '["am","was","were","be"]'::jsonb, 2, 'The subjunctive ''were'' is used in hypothetical conditions after ''if I''.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('eng-004', 'english-language', 'Grammar', 'easy', 'The news ___ surprising to everyone in the hall.', '["are","were","is","have been"]'::jsonb, 2, '''News'' is an uncountable noun that takes a singular verb.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('eng-005', 'english-language', 'Grammar', 'medium', 'He is one of the students who ___ very hard for the examination.', '["works","work","has worked","is working"]'::jsonb, 1, 'The relative pronoun ''who'' refers to ''students'', so the plural verb ''work'' is required.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('eng-006', 'english-language', 'Grammar', 'medium', 'By next December, Ada ___ her degree programme.', '["completes","will complete","will have completed","has completed"]'::jsonb, 2, 'The future perfect tense ''will have completed'' describes an action finished before a future time.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('eng-007', 'english-language', 'Grammar', 'hard', 'Hardly had the bell rung ___ the students rushed out.', '["than","when","then","that"]'::jsonb, 1, '''Hardly...when'' is the correct correlative construction.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('eng-008', 'english-language', 'Grammar', 'easy', 'Choose the correctly punctuated sentence.', '["My friend a doctor lives in Abuja.","My friend, a doctor, lives in Abuja.","My friend a doctor, lives in Abuja.","My friend; a doctor lives in Abuja."]'::jsonb, 1, 'An appositive (''a doctor'') is enclosed in commas.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('eng-009', 'english-language', 'Vocabulary', 'easy', 'A person who writes novels is called a ___.', '["playwright","novelist","biographer","columnist"]'::jsonb, 1, 'A novelist writes novels; a playwright writes plays; a biographer writes lives of people.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('eng-010', 'english-language', 'Vocabulary', 'medium', 'The word ''ephemeral'' means ___.', '["lasting forever","short-lived","extremely large","difficult to see"]'::jsonb, 1, 'Ephemeral describes something lasting for a very short time.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('eng-011', 'english-language', 'Vocabulary', 'medium', 'Choose the word nearest in meaning to ''candid''.', '["secretive","honest","rude","cautious"]'::jsonb, 1, 'Candid means frank and honest.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('eng-012', 'english-language', 'Vocabulary', 'medium', 'The opposite of ''frugal'' is ___.', '["economical","extravagant","careful","simple"]'::jsonb, 1, 'Frugal means thrifty; its opposite is extravagant.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('eng-013', 'english-language', 'Vocabulary', 'medium', 'The prefix ''audio-'' in ''audiovisual'' relates to ___.', '["sight","hearing","touch","movement"]'::jsonb, 1, 'Audio refers to sound or hearing; visual refers to sight.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('eng-014', 'english-language', 'Vocabulary', 'easy', 'A benevolent person is best described as ___.', '["kind","cruel","wealthy","proud"]'::jsonb, 0, 'Benevolent means well-meaning and kindly.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('eng-015', 'english-language', 'Vocabulary', 'medium', 'Someone who is loquacious ___.', '["talks a lot","eats a lot","sleeps a lot","works a lot"]'::jsonb, 0, 'Loquacious means very talkative.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('eng-016', 'english-language', 'Vocabulary', 'medium', 'Choose the word nearest in meaning to ''pragmatic''.', '["practical","poetic","careless","stubborn"]'::jsonb, 0, 'Pragmatic means dealing with things sensibly and practically.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('eng-017', 'english-language', 'Lexis & Structure', 'easy', 'Each of the girls ___ a new uniform.', '["have","has","are having","were having"]'::jsonb, 1, '''Each'' is singular and takes the singular verb ''has''.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('eng-018', 'english-language', 'Lexis & Structure', 'medium', 'The boy, together with his friends, ___ gone to the field.', '["have","are","has","were"]'::jsonb, 2, 'The subject is ''the boy''; the phrase ''together with his friends'' does not change the singular verb.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('eng-019', 'english-language', 'Lexis & Structure', 'easy', 'I look forward to ___ from you soon.', '["hear","hearing","heard","be hearing"]'::jsonb, 1, 'The preposition ''to'' is followed by a gerund, so ''hearing'' is correct.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('eng-020', 'english-language', 'Lexis & Structure', 'medium', 'She insisted on ___ the bill herself.', '["pay","paying","to pay","paid"]'::jsonb, 1, 'A preposition is followed by a gerund: ''insisted on paying''.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('eng-021', 'english-language', 'Lexis & Structure', 'medium', 'The teacher made the students ___ the passage aloud.', '["read","to read","reading","have read"]'::jsonb, 0, 'After the causative verb ''made'', the bare infinitive ''read'' is used.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('eng-022', 'english-language', 'Lexis & Structure', 'medium', 'He is used to ___ up early every morning.', '["wake","waking","woke","have woken"]'::jsonb, 1, '''Be used to'' is followed by a gerund: ''used to waking''.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('eng-023', 'english-language', 'Lexis & Structure', 'hard', 'Not only did she sing beautifully, ___ she also danced gracefully.', '["and","but","so","yet"]'::jsonb, 1, '''Not only...but also'' is the correct paired conjunction.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('eng-024', 'english-language', 'Lexis & Structure', 'easy', 'Choose the correct question tag: You are coming with us, ___?', '["are you","aren''t you","don''t you","isn''t it"]'::jsonb, 1, 'A positive statement takes a negative tag using the same auxiliary: ''aren''t you?''', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('eng-025', 'english-language', 'Comprehension', 'medium', 'Read the passage and answer the question. ''In many Nigerian communities, oral storytelling is more than entertainment. It is a library without shelves, preserving history, values and wisdom across generations.'' The main point of the passage is that oral storytelling ___.', '["is only for children","preserves culture and knowledge","has replaced written books","is becoming less popular"]'::jsonb, 1, 'The passage states that storytelling preserves history, values and wisdom, functioning like a library.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('eng-026', 'english-language', 'Comprehension', 'medium', 'Passage: ''The rain had turned the unpaved road into a ribbon of mud. Passengers pushed the overloaded bus while the driver revved the engine, and by the time they reached the town, everyone was coated in brown.'' The tone of the passage is best described as ___.', '["bitter and angry","humorous and vivid","sad and mournful","formal and scientific"]'::jsonb, 1, 'The vivid, slightly comic description of struggling through mud creates a humorous, vivid tone.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('eng-027', 'english-language', 'Comprehension', 'hard', 'Passage: ''The rain had turned the unpaved road into a ribbon of mud...'' The expression ''a ribbon of mud'' is an example of ___.', '["hyperbole","metaphor","personification","irony"]'::jsonb, 1, 'Mud is directly described as a ribbon, creating a metaphor.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('eng-028', 'english-language', 'Comprehension', 'medium', 'Read: ''Education is a lamp that lights the path of a nation. A country that neglects its schools builds its future on sand.'' The writer believes education is ___.', '["expensive","essential to national development","only for the rich","a temporary solution"]'::jsonb, 1, 'The lamp and sand images stress that education is foundational to national development.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('eng-029', 'english-language', 'Comprehension', 'hard', 'Read: ''Education is a lamp that lights the path of a nation.'' The figure of speech used here is ___.', '["simile","metaphor","onomatopoeia","alliteration"]'::jsonb, 1, 'Education is compared to a lamp without using ''like'' or ''as'', so it is a metaphor.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('eng-030', 'english-language', 'Comprehension', 'hard', 'Read: ''The chairman spoke for an hour without saying anything new. His words were a storm in a teacup.'' The writer suggests that the chairman''s speech was ___.', '["violent","impressive","overblown and empty","brief"]'::jsonb, 2, 'A storm in a teacup describes a great fuss about something trivial; combined with ''nothing new'', it means overblown and empty.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('eng-031', 'english-language', 'Comprehension', 'medium', 'Read: ''Although the village had no hospital, the nurse''s small clinic became a beacon of hope.'' The word ''although'' signals that the clinic was ___.', '["unnecessary","remarkable in difficult circumstances","poorly run","closed"]'::jsonb, 1, '''Although'' introduces a contrast: despite the absence of a hospital, the clinic was a source of hope.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('eng-032', 'english-language', 'Comprehension', 'medium', 'Read: ''The candidates entered the hall with pounding hearts. For many, the next two hours would shape their future.'' The phrase ''pounding hearts'' conveys ___.', '["anger","nervousness","excitement about lunch","confidence"]'::jsonb, 1, 'Pounding hearts is a physical sign of anxiety or nervousness.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('eng-033', 'english-language', 'Oral English', 'medium', 'Which word has a different vowel sound from the others?', '["bread","head","dead","bead"]'::jsonb, 3, '''Bread'', ''head'' and ''dead'' contain /e/; ''bead'' contains /iː/.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('eng-034', 'english-language', 'Oral English', 'medium', 'Which word contains the /ɪə/ sound?', '["near","nare","nurse","nor"]'::jsonb, 0, '''Near'' is pronounced /nɪə/, containing the centring diphthong /ɪə/.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('eng-035', 'english-language', 'Oral English', 'easy', 'The ''th'' in ''think'' is pronounced as a ___.', '["voiced dental fricative","voiceless dental fricative","voiced alveolar plosive","voiceless velar stop"]'::jsonb, 1, '''Think'' begins with /θ/, a voiceless dental fricative.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('eng-036', 'english-language', 'Oral English', 'medium', 'In which position does the primary stress fall in the word ''banana''?', '["First syllable","Second syllable","Third syllable","Every syllable equally"]'::jsonb, 1, 'Banana is stressed on the second syllable: /bəˈnɑːnə/.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('eng-037', 'english-language', 'Oral English', 'hard', 'Which word has a different pronunciation of ''ough'' from the others?', '["cough","rough","tough","dough"]'::jsonb, 3, '''Cough'', ''rough'' and ''tough'' end with /f/ or /ʌf/ patterns while ''dough'' is /dəʊ/.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('eng-038', 'english-language', 'Oral English', 'medium', 'A yes/no question in English normally ends with a ___ intonation.', '["falling","rising","level","falling-rising"]'::jsonb, 1, 'Yes/no questions typically use a rising intonation at the end.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('eng-039', 'english-language', 'Oral English', 'medium', 'In the word ''photography'', the primary stress falls on the ___ syllable.', '["first","second","third","fourth"]'::jsonb, 1, 'Photography is stressed on the second syllable: pho-TOG-ra-phy.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('eng-040', 'english-language', 'Oral English', 'easy', 'The plural ''boxes'' ends with which sound?', '["/s/","/z/","/ɪz/","/ʃ/"]'::jsonb, 2, 'Words ending in a sibilant take the extra syllable /ɪz/, as in ''boxes''.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('eng-041', 'english-language', 'Sentence Interpretation', 'easy', '''The early bird catches the worm'' means that ___.', '["birds are early risers","promptness brings advantages","worms are useful","latecomers succeed"]'::jsonb, 1, 'The proverb teaches that acting promptly gives a person an advantage.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('eng-042', 'english-language', 'Sentence Interpretation', 'medium', '''He has bitten more than he can chew'' means he ___.', '["eats too quickly","has taken on too much","is very hungry","has broken a tooth"]'::jsonb, 1, 'To bite off more than one can chew is to undertake more than one can manage.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('eng-043', 'english-language', 'Sentence Interpretation', 'medium', '''The ball is in your court'' means ___.', '["you should play tennis","it is your turn to act","you have lost the game","the decision is impossible"]'::jsonb, 1, 'The idiom means that the responsibility for the next action now belongs to you.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('eng-044', 'english-language', 'Sentence Interpretation', 'easy', '''A stitch in time saves nine'' advises us to ___.', '["sew our clothes","act early to prevent bigger problems","count to nine","avoid hard work"]'::jsonb, 1, 'Dealing with a problem early prevents it from becoming much larger.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('eng-045', 'english-language', 'Sentence Interpretation', 'medium', '''She let the cat out of the bag'' means she ___.', '["released a pet","revealed a secret","told a lie","became angry"]'::jsonb, 1, 'The idiom means to disclose a secret unintentionally.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('eng-046', 'english-language', 'Sentence Interpretation', 'hard', '''The chairman''s speech was a storm in a teacup'' means the speech was ___.', '["very violent","full of useful ideas","a great fuss over nothing","too long"]'::jsonb, 2, 'The idiom refers to unnecessary excitement about a trivial matter.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('eng-047', 'english-language', 'Sentence Interpretation', 'medium', '''He is a thorn in the flesh'' means he is ___.', '["a source of constant trouble","a close friend","a medical doctor","very thin"]'::jsonb, 0, 'A thorn in the flesh is a persistent source of annoyance or difficulty.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('eng-048', 'english-language', 'Sentence Interpretation', 'medium', '''Once bitten, twice shy'' means a person who has been hurt ___.', '["becomes bolder","becomes cautious","refuses all help","forgets quickly"]'::jsonb, 1, 'Experience of harm makes a person more careful in future.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('eng-049', 'english-language', 'Grammar', 'easy', 'The students, as well as their teacher, ___ present at the ceremony.', '["was","were","is","has been"]'::jsonb, 1, 'The compound subject is plural (''students''), so the plural verb ''were'' is used.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('eng-050', 'english-language', 'Vocabulary', 'hard', 'Choose the word nearest in meaning to ''ubiquitous''.', '["everywhere","rare","ancient","hidden"]'::jsonb, 0, 'Ubiquitous means present or found everywhere.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('mth-001', 'mathematics', 'Algebra', 'easy', 'Solve for x: 2x + 5 = 17.', '["4","6","7","11"]'::jsonb, 1, 'Subtract 5 from both sides: 2x = 12. Divide by 2: x = 6.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('mth-002', 'mathematics', 'Algebra', 'medium', 'The roots of x² − 5x + 6 = 0 are ___.', '["1 and 6","2 and 3","−2 and −3","5 and 6"]'::jsonb, 1, 'Factorising: (x − 2)(x − 3) = 0, so x = 2 or x = 3.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('mth-003', 'mathematics', 'Algebra', 'medium', 'Simplify (x³y²) ÷ (xy⁴).', '["x²/y²","x²y²","x⁴/y²","x²/y⁶"]'::jsonb, 0, 'Subtract indices for like bases: x³⁻¹ = x² and y²⁻⁴ = y⁻² = 1/y².', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('mth-004', 'mathematics', 'Algebra', 'easy', 'Factorise x² − 9.', '["(x − 3)(x + 3)","(x − 9)(x + 1)","(x − 3)²","(x + 3)²"]'::jsonb, 0, 'This is a difference of two squares: a² − b² = (a − b)(a + b).', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('mth-005', 'mathematics', 'Algebra', 'easy', 'If f(x) = 2x − 3, find f(4).', '["5","7","8","11"]'::jsonb, 0, 'Substitute x = 4: f(4) = 2(4) − 3 = 8 − 3 = 5.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('mth-006', 'mathematics', 'Algebra', 'medium', 'Solve 3(x − 2) = 2x + 1.', '["5","7","9","1"]'::jsonb, 1, 'Expand: 3x − 6 = 2x + 1. Subtract 2x: x − 6 = 1, so x = 7.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('mth-007', 'mathematics', 'Algebra', 'medium', 'If log₂ x = 5, then x = ___.', '["10","25","32","64"]'::jsonb, 2, 'log₂ x = 5 means 2⁵ = x, so x = 32.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('mth-008', 'mathematics', 'Algebra', 'hard', 'Simplify (2a²b)³.', '["6a⁵b³","8a⁶b³","8a⁵b³","6a⁶b³"]'::jsonb, 1, 'Cube each factor: 2³ = 8, (a²)³ = a⁶ and b³ = b³, giving 8a⁶b³.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('mth-009', 'mathematics', 'Geometry', 'easy', 'The sum of the interior angles of a hexagon is ___.', '["540°","720°","900°","1080°"]'::jsonb, 1, 'For an n-sided polygon the sum is (n − 2) × 180°. For n = 6: 4 × 180° = 720°.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('mth-010', 'mathematics', 'Geometry', 'easy', 'Find the area of a circle of radius 7 cm. (Take π = 22/7)', '["44 cm²","154 cm²","308 cm²","49 cm²"]'::jsonb, 1, 'Area = πr² = (22/7) × 7 × 7 = 154 cm².', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('mth-011', 'mathematics', 'Geometry', 'easy', 'A right-angled triangle has legs 3 cm and 4 cm. The hypotenuse is ___.', '["5 cm","6 cm","7 cm","12 cm"]'::jsonb, 0, 'By Pythagoras: hypotenuse = √(3² + 4²) = √25 = 5 cm.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('mth-012', 'mathematics', 'Geometry', 'medium', 'Each exterior angle of a regular pentagon is ___.', '["36°","72°","108°","144°"]'::jsonb, 1, 'Exterior angle = 360°/n = 360°/5 = 72°.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('mth-013', 'mathematics', 'Geometry', 'easy', 'The volume of a cube of side 4 cm is ___.', '["16 cm³","48 cm³","64 cm³","96 cm³"]'::jsonb, 2, 'Volume of a cube = s³ = 4³ = 64 cm³.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('mth-014', 'mathematics', 'Geometry', 'easy', 'Two angles lie on a straight line. If one is 65°, the other is ___.', '["25°","65°","115°","295°"]'::jsonb, 2, 'Angles on a straight line sum to 180°, so the other angle is 180° − 65° = 115°.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('mth-015', 'mathematics', 'Geometry', 'medium', 'A trapezium has parallel sides 8 cm and 12 cm and height 5 cm. Its area is ___.', '["40 cm²","50 cm²","60 cm²","100 cm²"]'::jsonb, 1, 'Area = ½(a + b)h = ½(8 + 12)(5) = 50 cm².', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('mth-016', 'mathematics', 'Geometry', 'medium', 'The circumference of a circle of radius 14 cm is ___. (Take π = 22/7)', '["44 cm","88 cm","154 cm","616 cm"]'::jsonb, 1, 'Circumference = 2πr = 2 × (22/7) × 14 = 88 cm.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('mth-017', 'mathematics', 'Trigonometry', 'easy', 'sin 30° = ___.', '["1/2","√2/2","√3/2","1"]'::jsonb, 0, 'The exact value of sin 30° is 1/2.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('mth-018', 'mathematics', 'Trigonometry', 'easy', 'cos 60° = ___.', '["0","1/2","√3/2","1"]'::jsonb, 1, 'The exact value of cos 60° is 1/2.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('mth-019', 'mathematics', 'Trigonometry', 'easy', 'tan 45° = ___.', '["0","1/2","1","√3"]'::jsonb, 2, 'tan 45° = sin 45°/cos 45° = 1.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('mth-020', 'mathematics', 'Trigonometry', 'medium', 'In a right-angled triangle, the side opposite angle θ is 3 cm and the hypotenuse is 5 cm. Find sin θ.', '["3/5","4/5","5/3","5/4"]'::jsonb, 0, 'sin θ = opposite/hypotenuse = 3/5.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('mth-021', 'mathematics', 'Trigonometry', 'easy', 'Which identity is always true for any angle θ?', '["sin²θ + cos²θ = 1","sin θ + cos θ = 1","sin²θ − cos²θ = 1","tan θ = sin θ cos θ"]'::jsonb, 0, 'The Pythagorean identity is sin²θ + cos²θ = 1.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('mth-022', 'mathematics', 'Trigonometry', 'easy', '180° is equal to ___ radians.', '["π/2","π","2π","3π/2"]'::jsonb, 1, 'Since 360° = 2π radians, 180° = π radians.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('mth-023', 'mathematics', 'Trigonometry', 'medium', 'cos 0° = ___.', '["0","1/2","1","−1"]'::jsonb, 2, 'The cosine of 0° is 1.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('mth-024', 'mathematics', 'Statistics', 'easy', 'Find the mean of 2, 4, 6, 8 and 10.', '["5","6","7","8"]'::jsonb, 1, 'Mean = (2 + 4 + 6 + 8 + 10)/5 = 30/5 = 6.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('mth-025', 'mathematics', 'Statistics', 'easy', 'Find the median of 3, 7, 9, 12 and 15.', '["7","9","12","15"]'::jsonb, 1, 'The values are already ordered; the middle value is 9.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('mth-026', 'mathematics', 'Statistics', 'easy', 'Find the mode of 2, 3, 3, 4, 5 and 3.', '["2","3","4","5"]'::jsonb, 1, 'The value 3 occurs most frequently.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('mth-027', 'mathematics', 'Statistics', 'easy', 'Find the range of 12, 7, 15 and 9.', '["6","8","12","15"]'::jsonb, 1, 'Range = highest − lowest = 15 − 7 = 8.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('mth-028', 'mathematics', 'Statistics', 'medium', 'The mean of five numbers is 8. Their total is ___.', '["13","32","40","48"]'::jsonb, 2, 'Total = mean × number of values = 8 × 5 = 40.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('mth-029', 'mathematics', 'Statistics', 'medium', 'Four numbers have a mean of 10. If three of them are 8, 9 and 12, the fourth is ___.', '["9","10","11","12"]'::jsonb, 2, 'Total = 4 × 10 = 40. The fourth number is 40 − (8 + 9 + 12) = 11.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('mth-030', 'mathematics', 'Statistics', 'medium', 'The class mark of the interval 20–30 is ___.', '["20","25","30","50"]'::jsonb, 1, 'Class mark = (lower + upper)/2 = (20 + 30)/2 = 25.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('mth-031', 'mathematics', 'Probability', 'easy', 'What is the probability of obtaining a head when a fair coin is tossed once?', '["1/4","1/3","1/2","1"]'::jsonb, 2, 'There are 2 equally likely outcomes and 1 favourable outcome, so P(head) = 1/2.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('mth-032', 'mathematics', 'Probability', 'easy', 'A fair die is rolled once. What is the probability of obtaining an even number?', '["1/6","1/3","1/2","2/3"]'::jsonb, 2, 'The even numbers are 2, 4 and 6: 3 favourable outcomes out of 6, so 1/2.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('mth-033', 'mathematics', 'Probability', 'easy', 'A bag contains 3 red balls and 7 blue balls. A ball is picked at random. Find P(red).', '["3/10","7/10","3/7","1/3"]'::jsonb, 0, 'There are 3 red balls out of 10 total, so P(red) = 3/10.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('mth-034', 'mathematics', 'Probability', 'medium', 'Two fair coins are tossed together. What is the probability that both show heads?', '["1/2","1/3","1/4","3/4"]'::jsonb, 2, 'P(HH) = 1/2 × 1/2 = 1/4.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('mth-035', 'mathematics', 'Probability', 'medium', 'A fair die is rolled once. What is the probability of not obtaining a 6?', '["1/6","5/6","1/2","2/3"]'::jsonb, 1, 'P(not 6) = 1 − P(6) = 1 − 1/6 = 5/6.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('mth-036', 'mathematics', 'Probability', 'hard', 'How many distinct arrangements can be made with the letters of the word BOOK?', '["4","6","12","24"]'::jsonb, 2, 'There are 4 letters with O repeated twice: 4!/2! = 24/2 = 12.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('mth-037', 'mathematics', 'Calculus', 'easy', 'Differentiate x³ with respect to x.', '["3x","x²","3x²","x⁴/4"]'::jsonb, 2, 'Using the power rule: d/dx(xⁿ) = nxⁿ⁻¹, so d/dx(x³) = 3x².', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('mth-038', 'mathematics', 'Calculus', 'easy', 'Differentiate 5x² with respect to x.', '["5x","10x","10x²","2x"]'::jsonb, 1, 'd/dx(5x²) = 2 × 5x = 10x.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('mth-039', 'mathematics', 'Calculus', 'easy', 'Evaluate ∫ 2x dx.', '["x² + C","2x² + C","x + C","2 + C"]'::jsonb, 0, 'Using the power rule for integration: ∫2x dx = 2(x²/2) + C = x² + C.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('mth-040', 'mathematics', 'Calculus', 'medium', 'Differentiate sin x with respect to x.', '["cos x","−cos x","−sin x","tan x"]'::jsonb, 0, 'The derivative of sin x is cos x.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('mth-041', 'mathematics', 'Calculus', 'easy', 'Find the gradient of the line y = 3x + 2.', '["2","3","5","1/3"]'::jsonb, 1, 'In y = mx + c, the gradient m is the coefficient of x, which is 3.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('mth-042', 'mathematics', 'Calculus', 'medium', 'Evaluate the definite integral of 2x from x = 0 to x = 1.', '["1","2","1/2","0"]'::jsonb, 0, '∫2x dx = x². Evaluating from 0 to 1 gives 1² − 0² = 1.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('mth-043', 'mathematics', 'Calculus', 'medium', 'Differentiate x² + 3x.', '["2x + 3","x + 3","2x","2x² + 3"]'::jsonb, 0, 'Differentiate term by term: d/dx(x²) = 2x and d/dx(3x) = 3, giving 2x + 3.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('mth-044', 'mathematics', 'Number Systems', 'easy', 'Convert 101₂ to base ten.', '["3","5","6","7"]'::jsonb, 1, '1×2² + 0×2¹ + 1×2⁰ = 4 + 0 + 1 = 5.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('mth-045', 'mathematics', 'Number Systems', 'medium', 'Express 25₁₀ in binary.', '["10011₂","11001₂","11010₂","10101₂"]'::jsonb, 1, '25 = 16 + 8 + 1 = 2⁴ + 2³ + 2⁰, which is 11001₂.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('mth-046', 'mathematics', 'Number Systems', 'easy', 'Convert 111₂ to base ten.', '["5","6","7","8"]'::jsonb, 2, '1×4 + 1×2 + 1×1 = 7.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('mth-047', 'mathematics', 'Number Systems', 'hard', 'Evaluate 7₈ + 5₈, giving the answer in base eight.', '["12₈","13₈","14₈","15₈"]'::jsonb, 2, 'In base eight, 7 + 5 = 12₁₀, which is 14₈ (1 eight and 4 units).', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('mth-048', 'mathematics', 'Number Systems', 'easy', 'Find the LCM of 12 and 18.', '["24","36","54","72"]'::jsonb, 1, 'Multiples of 12: 12, 24, 36...; multiples of 18: 18, 36...; the lowest common multiple is 36.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('mth-049', 'mathematics', 'Number Systems', 'easy', 'Find the HCF of 24 and 36.', '["6","8","12","18"]'::jsonb, 2, 'The highest common factor of 24 and 36 is 12.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('mth-050', 'mathematics', 'Number Systems', 'medium', 'Simplify √50.', '["2√5","5√2","10√5","25√2"]'::jsonb, 1, '√50 = √(25 × 2) = √25 × √2 = 5√2.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('phy-001', 'physics', 'Mechanics', 'easy', 'The SI unit of force is the ___.', '["joule","newton","watt","pascal"]'::jsonb, 1, 'Force is measured in newtons (N), where 1 N = 1 kg·m/s².', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('phy-002', 'physics', 'Mechanics', 'medium', 'A car starts from rest and accelerates at 2 m/s² for 5 s. Its final velocity is ___.', '["5 m/s","10 m/s","20 m/s","50 m/s"]'::jsonb, 1, 'Using v = u + at: v = 0 + (2)(5) = 10 m/s.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('phy-003', 'physics', 'Mechanics', 'easy', 'A body of mass 5 kg has a weight of ___ near the Earth''s surface. (Take g = 10 m/s²)', '["0.5 N","5 N","50 N","500 N"]'::jsonb, 2, 'Weight W = mg = 5 × 10 = 50 N.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('phy-004', 'physics', 'Mechanics', 'easy', 'Newton''s first law of motion is also known as the law of ___.', '["inertia","gravitation","momentum","action and reaction"]'::jsonb, 0, 'The first law states that a body remains in its state of rest or uniform motion unless acted on by a net force; this property is inertia.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('phy-005', 'physics', 'Mechanics', 'medium', 'A 2 kg object moves at 3 m/s. Its momentum is ___.', '["1.5 kg·m/s","5 kg·m/s","6 kg·m/s","12 kg·m/s"]'::jsonb, 2, 'Momentum p = mv = 2 × 3 = 6 kg·m/s.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('phy-006', 'physics', 'Mechanics', 'medium', 'A force of 10 N moves a body through 4 m in the direction of the force. The work done is ___.', '["2.5 J","14 J","40 J","400 J"]'::jsonb, 2, 'Work = force × distance = 10 × 4 = 40 J.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('phy-007', 'physics', 'Mechanics', 'medium', 'The kinetic energy of a 2 kg body moving at 4 m/s is ___.', '["8 J","16 J","32 J","64 J"]'::jsonb, 1, 'KE = ½mv² = ½ × 2 × 4² = 16 J.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('phy-008', 'physics', 'Mechanics', 'medium', 'A body moves with constant velocity. The net force acting on it is ___.', '["zero","equal to its weight","equal to its momentum","increasing"]'::jsonb, 0, 'Constant velocity means zero acceleration, so by Newton''s second law the net force is zero.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('phy-009', 'physics', 'Mechanics', 'medium', 'For a projectile on level ground, the maximum range is obtained at a launch angle of ___.', '["30°","45°","60°","90°"]'::jsonb, 1, 'The range R = u² sin 2θ/g is maximum when sin 2θ = 1, i.e. θ = 45°.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('phy-010', 'physics', 'Mechanics', 'easy', 'Pressure is defined as ___.', '["force × area","force ÷ area","work ÷ time","mass × velocity"]'::jsonb, 1, 'Pressure is the force acting normally per unit area: P = F/A.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('phy-011', 'physics', 'Electricity', 'easy', 'Ohm''s law is expressed as ___.', '["V = IR","V = I/R","I = VR","R = VI"]'::jsonb, 0, 'Ohm''s law states that V = IR, where V is voltage, I is current and R is resistance.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('phy-012', 'physics', 'Electricity', 'easy', 'Two resistors of 2 Ω and 3 Ω are connected in series. The effective resistance is ___.', '["1.2 Ω","2.5 Ω","5 Ω","6 Ω"]'::jsonb, 2, 'In series, resistances add: 2 + 3 = 5 Ω.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('phy-013', 'physics', 'Electricity', 'medium', 'Two 6 Ω resistors are connected in parallel. The effective resistance is ___.', '["3 Ω","6 Ω","12 Ω","36 Ω"]'::jsonb, 0, 'For two equal resistors in parallel, R = 6/2 = 3 Ω.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('phy-014', 'physics', 'Electricity', 'easy', 'The SI unit of electric current is the ___.', '["volt","ohm","ampere","coulomb"]'::jsonb, 2, 'Current is measured in amperes (A).', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('phy-015', 'physics', 'Electricity', 'medium', 'An appliance operates on 220 V and draws a current of 2 A. Its power is ___.', '["110 W","220 W","440 W","4400 W"]'::jsonb, 2, 'Power P = VI = 220 × 2 = 440 W.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('phy-016', 'physics', 'Electricity', 'medium', 'A current of 2 A flows for 10 s. The quantity of charge transferred is ___.', '["0.2 C","5 C","12 C","20 C"]'::jsonb, 3, 'Charge Q = It = 2 × 10 = 20 C.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('phy-017', 'physics', 'Electricity', 'easy', 'The main purpose of a fuse in a circuit is to ___.', '["increase current","protect against excess current","store charge","convert AC to DC"]'::jsonb, 1, 'A fuse melts and breaks the circuit when the current exceeds a safe value.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('phy-018', 'physics', 'Electricity', 'medium', 'Conventional current flows from ___ in an external circuit.', '["negative to positive","positive to negative","both directions","no fixed direction"]'::jsonb, 1, 'Conventional current is taken as the flow of positive charge from the positive terminal to the negative terminal.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('phy-019', 'physics', 'Electricity', 'medium', 'The unit of electrical energy commonly used for billing is the ___.', '["kilowatt-hour","newton","coulomb","ohm"]'::jsonb, 0, 'Electrical energy for billing is measured in kilowatt-hours (kWh).', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('phy-020', 'physics', 'Waves', 'easy', 'Wave speed is given by ___.', '["frequency ÷ wavelength","frequency × wavelength","wavelength ÷ frequency","frequency + wavelength"]'::jsonb, 1, 'The wave equation is v = fλ.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('phy-021', 'physics', 'Waves', 'easy', 'The SI unit of frequency is the ___.', '["metre","second","hertz","joule"]'::jsonb, 2, 'Frequency is measured in hertz (Hz), or cycles per second.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('phy-022', 'physics', 'Waves', 'easy', 'Sound cannot travel through ___.', '["solids","liquids","gases","a vacuum"]'::jsonb, 3, 'Sound is a mechanical wave and needs a material medium; it cannot travel through a vacuum.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('phy-023', 'physics', 'Waves', 'easy', 'Which of the following is a transverse wave?', '["sound wave","light wave","compression in a spring","rarefaction in air"]'::jsonb, 1, 'Light is an electromagnetic transverse wave; sound is longitudinal.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('phy-024', 'physics', 'Waves', 'medium', 'A wave of wavelength 2 m has a frequency of 50 Hz. Its speed is ___.', '["25 m/s","52 m/s","100 m/s","200 m/s"]'::jsonb, 2, 'v = fλ = 50 × 2 = 100 m/s.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('phy-025', 'physics', 'Waves', 'easy', 'The reflection of sound waves produces ___.', '["an echo","refraction","dispersion","diffraction"]'::jsonb, 0, 'An echo is heard when sound is reflected from a distant surface.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('phy-026', 'physics', 'Waves', 'easy', 'The pitch of a sound depends on its ___.', '["amplitude","frequency","speed","quality"]'::jsonb, 1, 'Pitch increases with frequency; amplitude determines loudness.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('phy-027', 'physics', 'Waves', 'medium', 'Resonance occurs when a system is driven at its ___.', '["minimum amplitude","natural frequency","maximum wavelength","zero frequency"]'::jsonb, 1, 'Resonance is maximum energy transfer at the natural frequency of the system.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('phy-028', 'physics', 'Optics', 'easy', 'The angle of incidence is always equal to the angle of ___ for reflection.', '["refraction","diffraction","reflection","dispersion"]'::jsonb, 2, 'The law of reflection states that the angle of incidence equals the angle of reflection.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('phy-029', 'physics', 'Optics', 'easy', 'A convex lens is a ___ lens.', '["diverging","converging","plane","cylindrical"]'::jsonb, 1, 'A convex lens converges parallel rays to a focal point.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('phy-030', 'physics', 'Optics', 'medium', 'The image formed on the retina of the human eye is ___.', '["virtual and upright","real and inverted","virtual and inverted","real and upright"]'::jsonb, 1, 'The eye''s lens forms a real, inverted image on the retina; the brain interprets it as upright.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('phy-031', 'physics', 'Optics', 'medium', 'Refraction of light occurs because light ___.', '["changes speed between media","is reflected","is absorbed","loses energy completely"]'::jsonb, 0, 'A change in speed as light crosses a boundary causes a change in direction, called refraction.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('phy-032', 'physics', 'Optics', 'easy', 'A convex mirror is used as a car rear-view mirror mainly because it ___.', '["forms a magnified image","gives a wider field of view","forms a real image","absorbs light"]'::jsonb, 1, 'A convex mirror gives a wide field of view and forms diminished, upright virtual images.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('phy-033', 'physics', 'Optics', 'hard', 'Total internal reflection can occur when light travels from ___.', '["air to glass","glass to air at an angle greater than the critical angle","air to water","a vacuum to any medium"]'::jsonb, 1, 'Total internal reflection occurs when light moves from a denser to a less dense medium and the angle exceeds the critical angle.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('phy-034', 'physics', 'Optics', 'medium', 'Magnification is defined as ___.', '["image height ÷ object height","object height ÷ image height","focal length × object distance","image distance + object distance"]'::jsonb, 0, 'Linear magnification m = image height/object height = image distance/object distance.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('phy-035', 'physics', 'Optics', 'medium', 'The splitting of white light into its component colours by a prism is called ___.', '["reflection","dispersion","diffraction","polarisation"]'::jsonb, 1, 'Dispersion occurs because different colours refract by different amounts in glass.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('phy-036', 'physics', 'Heat', 'easy', 'Heat can travel through a vacuum by ___.', '["conduction","convection","radiation","evaporation"]'::jsonb, 2, 'Radiation transfers energy by electromagnetic waves and does not require a medium.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('phy-037', 'physics', 'Heat', 'easy', 'At standard atmospheric pressure, pure water boils at ___.', '["0 °C","50 °C","100 °C","212 °C"]'::jsonb, 2, 'At standard atmospheric pressure, pure water boils at 100 °C (212 °F).', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('phy-038', 'physics', 'Heat', 'easy', 'The SI unit of specific heat capacity is ___.', '["J/kg·K","J·K","N/kg","kg/J"]'::jsonb, 0, 'Specific heat capacity is the energy needed to raise 1 kg of a substance by 1 K, measured in J/kg·K.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('phy-039', 'physics', 'Heat', 'easy', 'Convert 27 °C to kelvin.', '["27 K","246 K","273 K","300 K"]'::jsonb, 3, 'T(K) = T(°C) + 273 = 27 + 273 = 300 K.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('phy-040', 'physics', 'Heat', 'medium', 'Metals conduct heat well because they have ___.', '["free electrons","many air spaces","low density","high specific heat"]'::jsonb, 0, 'Free electrons in metals carry thermal energy rapidly through the lattice.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('phy-041', 'physics', 'Heat', 'medium', 'During a change of state, the temperature of a pure substance ___.', '["increases steadily","decreases steadily","remains constant","fluctuates randomly"]'::jsonb, 2, 'Latent heat is used to change state, so the temperature remains constant during the change.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('phy-042', 'physics', 'Heat', 'medium', 'A thermometer works because a physical property changes with ___.', '["mass","temperature","pressure only","volume only"]'::jsonb, 1, 'Thermometers rely on a property such as expansion that varies predictably with temperature.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('phy-043', 'physics', 'Heat', 'medium', 'The bimetallic strip in a thermostat bends because the two metals have different ___.', '["densities at 0 K","coefficients of expansion","melting points","colours"]'::jsonb, 1, 'Different rates of thermal expansion make the strip bend when heated or cooled.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('phy-044', 'physics', 'Modern Physics', 'medium', 'The photoelectric effect provides evidence that light ___.', '["is a longitudinal wave","behaves as a particle","cannot travel in a vacuum","has no energy"]'::jsonb, 1, 'The photoelectric effect is explained by photons, showing the particle nature of light.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('phy-045', 'physics', 'Modern Physics', 'easy', 'An alpha particle is identical to a ___.', '["helium nucleus","hydrogen nucleus","electron","photon"]'::jsonb, 0, 'An alpha particle consists of two protons and two neutrons, the same as a helium-4 nucleus.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('phy-046', 'physics', 'Modern Physics', 'medium', 'The time taken for half of the atoms in a radioactive sample to decay is called the ___.', '["half-life","decay constant","period","lifetime"]'::jsonb, 0, 'Half-life is the time for half the nuclei in a sample to decay.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('phy-047', 'physics', 'Modern Physics', 'easy', 'Einstein''s mass-energy equivalence is expressed as ___.', '["E = mc²","E = ½mv²","F = ma","E = hf"]'::jsonb, 0, 'E = mc² relates mass and energy, where c is the speed of light.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('phy-048', 'physics', 'Modern Physics', 'medium', 'Cathode rays are streams of ___.', '["protons","electrons","neutrons","alpha particles"]'::jsonb, 1, 'Cathode rays are beams of electrons emitted from a heated cathode in a vacuum tube.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('phy-049', 'physics', 'Modern Physics', 'easy', 'The atomic number of an element is the number of ___.', '["neutrons","protons","nucleons","electrons plus neutrons"]'::jsonb, 1, 'Atomic number Z equals the number of protons in the nucleus.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('phy-050', 'physics', 'Modern Physics', 'medium', 'Nuclear fission involves the ___.', '["splitting of a heavy nucleus","fusion of light nuclei","emission of light","capture of an electron"]'::jsonb, 0, 'Fission splits a heavy nucleus into lighter nuclei, releasing energy.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('chm-001', 'chemistry', 'Organic Chemistry', 'easy', 'The general formula of alkanes is ___.', '["CnH2n","CnH2n+2","CnH2n−2","CnHn"]'::jsonb, 1, 'Alkanes are saturated hydrocarbons with the general formula CnH2n+2.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('chm-002', 'chemistry', 'Organic Chemistry', 'easy', 'The molecular formula of methane is ___.', '["CH4","C2H6","CH3OH","CO2"]'::jsonb, 0, 'Methane, the simplest alkane, has one carbon and four hydrogen atoms: CH4.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('chm-003', 'chemistry', 'Organic Chemistry', 'easy', 'The functional group present in alkenes is ___.', '["a carbon–carbon double bond","a hydroxyl group","a carboxyl group","an amino group"]'::jsonb, 0, 'Alkenes contain a C=C double bond, making them unsaturated.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('chm-004', 'chemistry', 'Organic Chemistry', 'easy', 'The molecular formula of ethanol is ___.', '["CH3OH","C2H5OH","CH3COOH","C2H6"]'::jsonb, 1, 'Ethanol is C2H5OH, a two-carbon alcohol.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('chm-005', 'chemistry', 'Organic Chemistry', 'medium', 'The fermentation of glucose produces ethanol and ___.', '["oxygen","carbon dioxide","methane","hydrogen"]'::jsonb, 1, 'C6H12O6 → 2C2H5OH + 2CO2 during fermentation.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('chm-006', 'chemistry', 'Organic Chemistry', 'medium', 'A homologous series is a family of compounds that ___.', '["have identical molecular formulae","differ by a CH2 unit","contain only carbon","are all gases"]'::jsonb, 1, 'Members of a homologous series differ by one CH2 group and share similar chemical properties.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('chm-007', 'chemistry', 'Organic Chemistry', 'hard', 'Which pair are structural isomers?', '["Butane and 2-methylpropane","Ethene and ethyne","Methane and methanol","Propane and butane"]'::jsonb, 0, 'Butane and 2-methylpropane both have C4H10 but different arrangements of atoms.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('chm-008', 'chemistry', 'Organic Chemistry', 'medium', 'Ethene decolourises bromine water because it undergoes ___.', '["addition","substitution","elimination","oxidation to CO2"]'::jsonb, 0, 'The C=C double bond undergoes addition with bromine, removing its colour.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('chm-009', 'chemistry', 'Organic Chemistry', 'medium', 'The reaction between an alcohol and a carboxylic acid produces ___.', '["an ester","an alkane","an amine","a ketone"]'::jsonb, 0, 'Esterification produces an ester and water.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('chm-010', 'chemistry', 'Organic Chemistry', 'medium', 'Polymerisation of ethene produces ___.', '["polythene","PVC","nylon","polystyrene"]'::jsonb, 0, 'Addition polymerisation of ethene monomers produces polythene (polyethene).', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('chm-011', 'chemistry', 'Atomic Structure', 'easy', 'A chlorine atom has 17 protons and 18 neutrons. What is its mass number?', '["17","18","35","36"]'::jsonb, 2, 'Mass number is the sum of protons and neutrons: 17 + 18 = 35.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('chm-012', 'chemistry', 'Atomic Structure', 'easy', 'Mass number is the sum of ___.', '["protons and electrons","protons and neutrons","neutrons and electrons","protons only"]'::jsonb, 1, 'Mass number = number of protons + number of neutrons.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('chm-013', 'chemistry', 'Atomic Structure', 'easy', 'The electron configuration of oxygen (atomic number 8) is ___.', '["2, 6","2, 8","8","2, 4, 2"]'::jsonb, 0, 'Oxygen has 8 electrons arranged as 2 in the first shell and 6 in the second.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('chm-014', 'chemistry', 'Atomic Structure', 'medium', 'Isotopes of an element have the same number of ___.', '["neutrons but different protons","protons but different neutrons","protons and neutrons but different electrons","electrons and neutrons"]'::jsonb, 1, 'Isotopes have the same atomic number (protons) but different mass numbers due to different neutrons.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('chm-015', 'chemistry', 'Atomic Structure', 'medium', 'The discovery of the nucleus is associated with ___.', '["J. J. Thomson","Ernest Rutherford","Niels Bohr","John Dalton"]'::jsonb, 1, 'Rutherford''s gold-foil experiment led to the nuclear model of the atom.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('chm-016', 'chemistry', 'Atomic Structure', 'easy', 'Sodium has an atomic number of 11. Its electron configuration is ___.', '["2, 8, 1","2, 9","2, 8, 2","2, 7, 2"]'::jsonb, 0, 'Sodium has 11 electrons: 2 + 8 + 1.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('chm-017', 'chemistry', 'Atomic Structure', 'medium', 'Chlorine exists mainly as two isotopes of mass numbers 35 and 37. This means the isotopes have ___.', '["different protons","different neutrons","different electrons","different chemical formulae"]'::jsonb, 1, 'Both isotopes have 17 protons; they differ in the number of neutrons (18 and 20).', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('chm-018', 'chemistry', 'Atomic Structure', 'hard', 'The maximum number of electrons in a principal shell is given by ___.', '["n","2n","n²","2n²"]'::jsonb, 3, 'The maximum electron capacity of a shell is 2n², where n is the principal quantum number.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('chm-019', 'chemistry', 'Atomic Structure', 'medium', 'A sodium ion, Na⁺, is formed when a sodium atom ___.', '["gains one electron","loses one electron","gains one proton","loses one neutron"]'::jsonb, 1, 'Na loses one valence electron to form Na⁺ with a stable noble-gas configuration.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('chm-020', 'chemistry', 'Atomic Structure', 'easy', 'The neutron has a charge of ___.', '["+1","−1","0","+2"]'::jsonb, 2, 'Neutrons are neutral particles.', 'practice', false, '2026-01-01T00:00:00.000Z'),
