  ('chm-022', 'chemistry', 'Chemical Bonding', 'easy', 'A covalent bond involves the ___ of electrons.', '["transfer","sharing","complete loss","emission"]'::jsonb, 1, 'Covalent bonds form when atoms share pairs of electrons.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('chm-023', 'chemistry', 'Chemical Bonding', 'easy', 'Which compound is ionic?', '["NaCl","CO2","CH4","H2O"]'::jsonb, 0, 'Sodium chloride is formed by electron transfer between sodium and chlorine.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('chm-024', 'chemistry', 'Chemical Bonding', 'medium', 'Water is a polar covalent compound because ___.', '["it contains ions","oxygen is more electronegative than hydrogen","it has no bonds","it is a gas"]'::jsonb, 1, 'The unequal sharing of electrons, due to oxygen''s higher electronegativity, makes water polar.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('chm-025', 'chemistry', 'Chemical Bonding', 'medium', 'Metallic bonding is best described as ___.', '["positive ions in a sea of delocalised electrons","shared electron pairs only","transfer of protons","hydrogen bonding"]'::jsonb, 0, 'Metal cations are held together by a sea of delocalised valence electrons.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('chm-026', 'chemistry', 'Chemical Bonding', 'easy', 'Noble gases are chemically unreactive because they ___.', '["have full outer shells","have one electron","are metals","form ionic bonds"]'::jsonb, 0, 'Noble gases have stable, full outer electron shells.', 'practice', false, '2026-01-01T00:00:00.000Z'),
