  ('chm-028', 'chemistry', 'Chemical Bonding', 'medium', 'Electrovalent compounds generally have high melting points because ___.', '["they have weak forces","strong electrostatic forces hold the ions","they are covalent","they contain molecules"]'::jsonb, 1, 'Strong electrostatic attraction between oppositely charged ions requires much energy to break.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('chm-029', 'chemistry', 'Chemical Bonding', 'medium', 'Hydrogen bonding in water explains its ___.', '["high boiling point","low density only","colour","radioactivity"]'::jsonb, 0, 'Hydrogen bonds between water molecules are strong enough to raise its boiling point.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('chm-030', 'chemistry', 'Chemical Bonding', 'hard', 'The bond in an oxygen molecule, O2, is a ___.', '["single bond","double bond","triple bond","ionic bond"]'::jsonb, 1, 'The oxygen atoms share two pairs of electrons, forming a double bond.', 'practice', false, '2026-01-01T00:00:00.000Z'),
