  ('bio-030', 'biology', 'Human Anatomy', 'easy', 'Most absorption of digested food occurs in the ___.', '["mouth","stomach","small intestine","large intestine"]'::jsonb, 2, 'The small intestine has villi that increase surface area for absorption.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('bio-031', 'biology', 'Human Anatomy', 'easy', 'Red blood cells transport oxygen because they contain ___.', '["haemoglobin","chlorophyll","insulin","fibrin"]'::jsonb, 0, 'Haemoglobin binds oxygen in the lungs and releases it in tissues.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('bio-032', 'biology', 'Human Anatomy', 'medium', 'The basic functional unit of the nervous system is the ___.', '["neuron","nephron","alveolus","villus"]'::jsonb, 0, 'Neurons transmit electrical impulses through the nervous system.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('bio-033', 'biology', 'Human Anatomy', 'medium', 'The liver plays a role in ___.', '["producing bile and detoxifying substances","pumping blood","filtering urine","gas exchange"]'::jsonb, 0, 'The liver produces bile, stores glycogen and detoxifies harmful substances.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('bio-034', 'biology', 'Human Anatomy', 'medium', 'Insulin is produced by the ___.', '["liver","pancreas","kidney","spleen"]'::jsonb, 1, 'Beta cells of the pancreatic islets secrete insulin.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('bio-035', 'biology', 'Evolution', 'easy', 'The theory of natural selection was proposed by ___.', '["Gregor Mendel","Charles Darwin","Louis Pasteur","Robert Hooke"]'::jsonb, 1, 'Charles Darwin proposed natural selection in ''On the Origin of Species''.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('bio-036', 'biology', 'Evolution', 'medium', 'Homologous structures provide evidence for evolution because they ___.', '["perform identical functions","share a common ancestry despite different functions","are always vestigial","are found only in fossils"]'::jsonb, 1, 'Homologous structures have similar underlying anatomy inherited from a common ancestor.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('bio-037', 'biology', 'Evolution', 'easy', 'Variation within a species is important for evolution because it ___.', '["prevents reproduction","provides material for natural selection","reduces population","stops mutation"]'::jsonb, 1, 'Natural selection acts on heritable variation.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('bio-038', 'biology', 'Evolution', 'medium', 'An adaptation is a feature that ___.', '["reduces survival","improves an organism''s chance of survival and reproduction","is always harmful","appears only in fossils"]'::jsonb, 1, 'Adaptations enhance fitness in a particular environment.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('bio-039', 'biology', 'Evolution', 'medium', 'Fossil records provide evidence of evolution by showing ___.', '["change in organisms over geological time","that all species appeared at once","that evolution is impossible","only living species"]'::jsonb, 0, 'Fossils document gradual changes and extinct forms over time.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('bio-040', 'biology', 'Evolution', 'hard', 'Speciation is the process by which ___.', '["new species form","organisms become extinct","individuals adapt within a lifetime","genes mutate randomly"]'::jsonb, 0, 'Speciation is the formation of new and distinct species through evolution.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('bio-041', 'biology', 'Evolution', 'medium', 'Vestigial structures such as the human appendix are evidence of ___.', '["common ancestry","perfect design","spontaneous generation","recent creation"]'::jsonb, 0, 'Vestigial organs are reduced remnants inherited from ancestors in which they were functional.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('bio-042', 'biology', 'Evolution', 'medium', 'The rapid evolution of antibiotic-resistant bacteria is an example of ___.', '["natural selection","artificial selection by humans","Lamarckian inheritance","mutation only"]'::jsonb, 0, 'Antibiotics select for resistant bacteria, which survive and reproduce.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('bio-043', 'biology', 'Reproduction', 'easy', 'Fertilisation is the fusion of ___.', '["two somatic cells","a male and a female gamete","two eggs","two sperm cells"]'::jsonb, 1, 'Fertilisation is the fusion of a sperm and an egg to form a zygote.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('bio-044', 'biology', 'Reproduction', 'easy', 'Pollination is the transfer of pollen from ___.', '["the stigma to the anther","the anther to the stigma","the root to the leaf","the ovary to the style"]'::jsonb, 1, 'Pollen moves from the anther (male part) to the stigma (female part).', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('bio-045', 'biology', 'Reproduction', 'easy', 'Sperm cells are produced in the ___.', '["ovaries","testes","uterus","prostate"]'::jsonb, 1, 'The testes produce sperm and testosterone.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('bio-046', 'biology', 'Reproduction', 'medium', 'Ovulation is the release of ___.', '["an egg from the ovary","sperm from the testes","milk from the breast","blood from the uterus"]'::jsonb, 0, 'Ovulation is the release of a mature egg from the ovary, usually mid-cycle.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('bio-047', 'biology', 'Reproduction', 'medium', 'The placenta allows ___.', '["exchange of substances between mother and foetus","the foetus to breathe air","the mother to produce milk","the foetus to eat food"]'::jsonb, 0, 'The placenta facilitates exchange of nutrients, oxygen and waste between mother and foetus.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('bio-048', 'biology', 'Reproduction', 'medium', 'Asexual reproduction produces offspring that are ___.', '["genetically identical to the parent","always male","genetically varied","always sterile"]'::jsonb, 0, 'Asexual reproduction involves no gamete fusion and produces clones.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('bio-049', 'biology', 'Reproduction', 'easy', 'The transfer of seeds away from the parent plant is called ___.', '["germination","dispersal","pollination","fertilisation"]'::jsonb, 1, 'Seed dispersal reduces competition and spreads the species.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('bio-050', 'biology', 'Reproduction', 'medium', 'Menstruation occurs when ___.', '["an egg is fertilised","the uterine lining breaks down","ovulation stops permanently","sperm are produced"]'::jsonb, 1, 'If fertilisation does not occur, the thickened uterine lining is shed as menstruation.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('lit-001', 'literature-in-english', 'Drama', 'easy', 'A play is written primarily to be ___.', '["read silently","performed on stage","sold as a novel","recited as a poem"]'::jsonb, 1, 'Drama is a literary form composed for performance by actors before an audience.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('lit-002', 'literature-in-english', 'Drama', 'easy', 'The person who writes a play is called a ___.', '["novelist","poet","playwright","critic"]'::jsonb, 2, 'A playwright writes plays; Shakespeare is a famous example.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('lit-003', 'literature-in-english', 'Drama', 'medium', 'A speech in which a character reveals private thoughts to the audience alone is called a ___.', '["dialogue","soliloquy","monologue to other characters","prologue"]'::jsonb, 1, 'A soliloquy is spoken by a character alone on stage, revealing inner thoughts.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('lit-004', 'literature-in-english', 'Drama', 'medium', 'The main character of a tragedy is called the ___.', '["chorus","protagonist","antagonist","narrator"]'::jsonb, 1, 'The protagonist is the central character; the antagonist opposes them.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('lit-005', 'literature-in-english', 'Drama', 'medium', 'A tragic flaw in a tragic hero is known as ___.', '["hamartia","hubris","catharsis","anagnorisis"]'::jsonb, 0, 'Hamartia is the error or flaw that leads to the hero''s downfall.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('lit-006', 'literature-in-english', 'Drama', 'medium', 'The emotional release experienced by the audience at the end of a tragedy is called ___.', '["catharsis","peripeteia","hubris","pathos"]'::jsonb, 0, 'Catharsis is the purging of emotions, especially pity and fear.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('lit-007', 'literature-in-english', 'Drama', 'easy', 'Stage directions in a play are usually written in ___.', '["italics or brackets","capital letters only","rhyme","verse"]'::jsonb, 0, 'Stage directions are conventionally italicised or placed in brackets.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('lit-008', 'literature-in-english', 'Drama', 'medium', 'A group of actors who comment on the action in classical drama is the ___.', '["chorus","cast","crew","ensemble lead"]'::jsonb, 0, 'The chorus comments on and interprets the action, especially in Greek drama.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('lit-009', 'literature-in-english', 'Drama', 'medium', 'A one-act play has ___.', '["one act","one scene only","one character only","no dialogue"]'::jsonb, 0, 'A one-act play is complete in a single act.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('lit-010', 'literature-in-english', 'Drama', 'hard', 'Dramatic irony occurs when the audience ___.', '["knows more than the characters on stage","laughs at a joke","is surprised by the ending","cannot hear the actors"]'::jsonb, 0, 'In dramatic irony, the audience understands a situation that the characters do not.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('lit-011', 'literature-in-english', 'Poetry', 'easy', 'A poem of fourteen lines is called a ___.', '["sonnet","ode","ballad","haiku"]'::jsonb, 0, 'A sonnet is a fourteen-line poem, usually with a set rhyme scheme.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('lit-012', 'literature-in-english', 'Poetry', 'easy', 'A group of lines in a poem is called a ___.', '["stanza","paragraph","chapter","sentence"]'::jsonb, 0, 'Stanzas are the basic grouped units of a poem, like paragraphs in prose.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('lit-013', 'literature-in-english', 'Poetry', 'medium', 'The pattern of stressed and unstressed syllables in poetry is called ___.', '["rhythm","rhyme","alliteration","onomatopoeia"]'::jsonb, 0, 'Rhythm is the measured flow of stressed and unstressed syllables.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('lit-014', 'literature-in-english', 'Poetry', 'medium', '''The moon walked across the silent sky'' is an example of ___.', '["personification","simile","hyperbole","alliteration"]'::jsonb, 0, 'The moon is given the human ability to walk, so it is personified.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('lit-015', 'literature-in-english', 'Poetry', 'easy', 'A word that imitates the sound it describes is called ___.', '["onomatopoeia","metaphor","irony","assonance"]'::jsonb, 0, 'Examples include ''buzz'', ''hiss'' and ''bang''.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('lit-016', 'literature-in-english', 'Poetry', 'medium', 'A comparison using ''like'' or ''as'' is a ___.', '["simile","metaphor","personification","hyperbole"]'::jsonb, 0, 'A simile compares two things using ''like'' or ''as''.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('lit-017', 'literature-in-english', 'Poetry', 'medium', 'The repetition of initial consonant sounds is called ___.', '["alliteration","assonance","consonance","rhyme"]'::jsonb, 0, 'Alliteration is the repetition of initial consonant sounds, as in ''slippery slope''.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('lit-018', 'literature-in-english', 'Poetry', 'medium', 'An ode is a poem that ___.', '["praises or celebrates someone or something","tells a comic story","is always sad","has no rhyme"]'::jsonb, 0, 'An ode is a formal lyric poem praising a person, object or idea.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('lit-019', 'literature-in-english', 'Poetry', 'hard', 'The volta in a sonnet refers to the ___.', '["turn in thought or argument","rhyme scheme","number of lines","poet''s name"]'::jsonb, 0, 'The volta is a shift in tone, argument or perspective, often between the octave and sestet.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('lit-020', 'literature-in-english', 'Poetry', 'medium', 'Enjambment occurs when a sentence ___.', '["runs from one line into the next without a pause","ends at the end of a line","has no punctuation","rhymes internally"]'::jsonb, 0, 'Enjambment carries a sentence across a line break without a pause.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('lit-021', 'literature-in-english', 'Prose', 'easy', 'A long narrative work of fiction is called a ___.', '["novel","poem","play","essay"]'::jsonb, 0, 'A novel is an extended fictional prose narrative.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('lit-022', 'literature-in-english', 'Prose', 'medium', 'The perspective from which a story is told is called the ___.', '["point of view","plot","setting","theme"]'::jsonb, 0, 'Point of view describes who narrates and how much they know.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('lit-023', 'literature-in-english', 'Prose', 'easy', 'The sequence of events in a story is the ___.', '["plot","setting","theme","style"]'::jsonb, 0, 'Plot is the arranged sequence of events and conflicts in a narrative.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('lit-024', 'literature-in-english', 'Prose', 'easy', 'The time and place in which a story occurs is the ___.', '["setting","plot","climax","tone"]'::jsonb, 0, 'Setting is the social and physical environment of the narrative.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('lit-025', 'literature-in-english', 'Prose', 'medium', 'A story within a story is called a ___.', '["frame narrative","flashback","fable","parody"]'::jsonb, 0, 'A frame narrative encloses one or more inner stories.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('lit-026', 'literature-in-english', 'Prose', 'medium', 'The central idea or message of a literary work is its ___.', '["theme","plot","setting","character"]'::jsonb, 0, 'Theme is the underlying idea or insight explored by a text.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('lit-027', 'literature-in-english', 'Prose', 'medium', 'A character who changes significantly during a story is a ___.', '["dynamic character","flat character","static character","stock character"]'::jsonb, 0, 'Dynamic characters develop or change because of events.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('lit-028', 'literature-in-english', 'Prose', 'medium', 'An omniscient narrator ___.', '["knows everything about the characters and events","participates in the story","knows only one character''s thoughts","is unreliable"]'::jsonb, 0, 'Omniscient means ''all-knowing''; the narrator has access to all minds and events.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('lit-029', 'literature-in-english', 'Prose', 'hard', 'A novel that traces a character''s growth from childhood to maturity is called a ___.', '["bildungsroman","gothic novel","epistolary novel","satire"]'::jsonb, 0, 'Bildungsroman is a coming-of-age novel focused on personal development.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('lit-030', 'literature-in-english', 'Prose', 'easy', 'A short story is usually ___.', '["shorter than a novel with fewer characters and events","always non-fiction","written only in verse","performed on stage"]'::jsonb, 0, 'A short story is a brief fictional narrative, often focused on a single incident.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('lit-031', 'literature-in-english', 'Literary Terms', 'easy', 'A metaphor is a direct comparison that ___.', '["uses ''like'' or ''as''","does not use ''like'' or ''as''","imitates sound","repeats vowels"]'::jsonb, 1, 'A metaphor states that one thing is another without using ''like'' or ''as''.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('lit-032', 'literature-in-english', 'Literary Terms', 'easy', 'Exaggeration for emphasis is called ___.', '["hyperbole","litotes","irony","oxymoron"]'::jsonb, 0, 'Hyperbole is deliberate exaggeration, such as ''I have told you a million times''.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('lit-033', 'literature-in-english', 'Literary Terms', 'medium', 'An oxymoron combines ___.', '["two contradictory terms","two rhyming lines","two narrators","two settings"]'::jsonb, 0, 'An oxymoron joins opposite ideas, such as ''bitter-sweet''.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('lit-034', 'literature-in-english', 'Literary Terms', 'medium', 'A figure of speech in which an idea is expressed as less than it is, often by denying the opposite, is ___.', '["litotes","hyperbole","metonymy","synecdoche"]'::jsonb, 0, 'Litotes uses understatement through negation, e.g. ''not bad'' for ''very good''.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('lit-035', 'literature-in-english', 'Literary Terms', 'medium', 'Substituting a related term for something (e.g. ''the crown'' for the monarchy) is ___.', '["metonymy","simile","onomatopoeia","allusion"]'::jsonb, 0, 'Metonymy replaces a thing with something closely associated with it.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('lit-036', 'literature-in-english', 'Literary Terms', 'medium', 'A reference to a well-known person, event or text is an ___.', '["allusion","illusion","allegory","alliteration"]'::jsonb, 0, 'Allusion is an indirect reference to something outside the text.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('lit-037', 'literature-in-english', 'Literary Terms', 'easy', 'Irony involves a contrast between ___.', '["appearance and reality","two rhymes","two settings","two stanzas"]'::jsonb, 0, 'Irony arises from a contrast between expectation and reality or meaning and saying.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('lit-038', 'literature-in-english', 'Literary Terms', 'medium', 'An allegory is a story in which ___.', '["characters and events have symbolic meaning","all characters are animals","nothing is symbolic","the ending is always sad"]'::jsonb, 0, 'An allegory uses a narrative to convey a deeper moral or political meaning.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('lit-039', 'literature-in-english', 'Literary Terms', 'medium', 'The repetition of vowel sounds within nearby words is called ___.', '["assonance","alliteration","consonance","rhyme"]'::jsonb, 0, 'Assonance repeats vowel sounds, as in ''the rain in Spain''.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('lit-040', 'literature-in-english', 'Literary Terms', 'hard', 'A motif is ___.', '["a recurring image, idea or symbol","the main character","the final line","a type of play"]'::jsonb, 0, 'A motif is a repeated element that develops a theme.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('lit-041', 'literature-in-english', 'African Literature', 'medium', 'Chinua Achebe''s ''Things Fall Apart'' is set in ___.', '["Igbo society before and during colonial contact","Lagos in the 1990s","ancient Egypt","apartheid South Africa"]'::jsonb, 0, 'The novel portrays Igbo life in Umuofia and the arrival of British colonial rule.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('lit-042', 'literature-in-english', 'African Literature', 'medium', 'The protagonist of ''Things Fall Apart'' is ___.', '["Okonkwo","Obi","Ezeulu","Unoka"]'::jsonb, 0, 'Okonkwo is the proud, forceful protagonist of Achebe''s novel.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('lit-043', 'literature-in-english', 'African Literature', 'medium', 'Wole Soyinka is best known as a ___.', '["playwright and poet","novelist only","historian","journalist"]'::jsonb, 0, 'Soyinka is a Nobel-winning playwright, poet and essayist.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('lit-044', 'literature-in-english', 'African Literature', 'medium', '''The Lion and the Jewel'' was written by ___.', '["Wole Soyinka","Chinua Achebe","Ngũgĩ wa Thiong''o","Femi Osofisan"]'::jsonb, 0, 'Soyinka''s play is set in the village of Ilujinle.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('lit-045', 'literature-in-english', 'African Literature', 'medium', 'In ''The Lion and the Jewel'', the ''lion'' refers to ___.', '["Lakunle","Baroka","Sadiku","Sidi"]'::jsonb, 1, 'Baroka, the Bale of Ilujinle, is the ''lion'', while Sidi, the beautiful village girl, is the ''jewel''.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('lit-046', 'literature-in-english', 'African Literature', 'easy', 'The author of ''Purple Hibiscus'' is ___.', '["Chimamanda Ngozi Adichie","Buchi Emecheta","Ama Ata Aidoo","Tsitsi Dangarembga"]'::jsonb, 0, 'Adichie published ''Purple Hibiscus'' in 2003.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('lit-047', 'literature-in-english', 'African Literature', 'medium', '''Second Class Citizen'' is a novel by ___.', '["Buchi Emecheta","Chimamanda Ngozi Adichie","Mariama Bâ","Sefi Atta"]'::jsonb, 0, 'Buchi Emecheta''s novel follows Adah''s life in Nigeria and London.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('lit-048', 'literature-in-english', 'African Literature', 'medium', 'Ngũgĩ wa Thiong''o''s ''The River Between'' explores conflict between ___.', '["tradition and Christianity","two football clubs","city and village police","two universities"]'::jsonb, 0, 'The novel dramatises the clash between Gikuyu tradition and colonial Christianity.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('lit-049', 'literature-in-english', 'African Literature', 'medium', 'A major theme of much postcolonial African literature is ___.', '["identity and the effects of colonialism","space travel","medieval chivalry","industrial accounting"]'::jsonb, 0, 'Postcolonial writing often interrogates identity, power, language and colonial legacies.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('lit-050', 'literature-in-english', 'African Literature', 'hard', '''The beautyful ones are not yet born'' (Ayi Kwei Armah) is an example of ___.', '["post-independence disillusionment fiction","romantic comedy","epic poetry","children''s literature"]'::jsonb, 0, 'The novel critiques corruption and dashed hopes in post-independence Ghana.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('gov-001', 'government', 'Constitution', 'easy', 'A constitution is best defined as ___.', '["a set of laws made by a king","the body of fundamental principles by which a state is governed","a list of political parties","a document containing election results"]'::jsonb, 1, 'A constitution establishes the framework, powers and limits of government.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('gov-002', 'government', 'Constitution', 'easy', 'A constitution that is contained in a single document is described as ___.', '["unwritten","written","flexible","customary"]'::jsonb, 1, 'A written constitution is codified in one authoritative document.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('gov-003', 'government', 'Constitution', 'medium', 'A rigid constitution is one that ___.', '["can be amended by ordinary legislation","is difficult to amend","is not written","has no bill of rights"]'::jsonb, 1, 'Rigid constitutions require special procedures and often supermajorities for amendment.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('gov-004', 'government', 'Constitution', 'medium', 'The principle of separation of powers is associated with ___.', '["Baron de Montesquieu","Karl Marx","John Locke only","Thomas Hobbes only"]'::jsonb, 0, 'Montesquieu articulated the separation of legislative, executive and judicial powers.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('gov-005', 'government', 'Constitution', 'medium', 'The rule of law was popularised by ___.', '["A. V. Dicey","Max Weber","Aristotle","Jean Bodin"]'::jsonb, 0, 'A. V. Dicey''s formulation emphasises equality before the law and due process.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('gov-006', 'government', 'Constitution', 'medium', 'Constitutional supremacy means that ___.', '["the president is above the law","the constitution is the highest law of the land","parliament can ignore the courts","customary law ranks above statute"]'::jsonb, 1, 'All laws and government actions must conform to the constitution.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('gov-007', 'government', 'Constitution', 'medium', 'A federal constitution typically ___.', '["concentrates all power at the centre","divides powers between central and regional governments","abolishes the judiciary","is always unwritten"]'::jsonb, 1, 'Federalism constitutionally divides authority between federal and state governments.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('gov-008', 'government', 'Constitution', 'medium', 'Fundamental human rights in Nigeria are protected mainly in ___.', '["Chapter II of the Constitution","Chapter IV of the Constitution","the Electoral Act","the Criminal Code"]'::jsonb, 1, 'Chapter IV of the 1999 Constitution contains fundamental rights enforceable in court.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('gov-009', 'government', 'Federalism', 'easy', 'Federalism is a system in which power is ___.', '["held by one central government","shared between central and component governments","held only by traditional rulers","exercised by the military"]'::jsonb, 1, 'Federalism divides authority between a central government and constituent units.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('gov-010', 'government', 'Federalism', 'easy', 'Nigeria currently has ___ states and the Federal Capital Territory.', '["30","32","36","40"]'::jsonb, 2, 'Nigeria has 36 states and the Federal Capital Territory, Abuja.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('gov-011', 'government', 'Federalism', 'medium', 'The exclusive legislative list contains matters on which ___.', '["only states can legislate","only the federal government can legislate","both tiers can legislate","local governments legislate alone"]'::jsonb, 1, 'Exclusive-list matters, such as defence and foreign affairs, are reserved for the federal government.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('gov-012', 'government', 'Federalism', 'medium', 'The concurrent legislative list contains matters on which ___.', '["only the federal government legislates","both federal and state governments may legislate","only traditional rulers decide","no government legislates"]'::jsonb, 1, 'Federal and state governments share legislative competence on concurrent matters, with federal law prevailing in conflict.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('gov-013', 'government', 'Federalism', 'medium', 'The residual legislative list covers matters on which ___.', '["only state governments can legislate","only the federal government can legislate","local governments legislate","foreign governments legislate"]'::jsonb, 0, 'Residual matters are left to the states under Nigerian federalism.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('gov-014', 'government', 'Federalism', 'easy', 'Local government is often described as the ___ tier of government.', '["first","second","third","fourth"]'::jsonb, 2, 'Nigeria operates a three-tier system: federal, state and local government.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('gov-015', 'government', 'Federalism', 'medium', 'Revenue from the Federation Account is shared among the tiers of government through ___.', '["the Central Bank","the Federation Account Allocation Committee","the Senate","the Supreme Court"]'::jsonb, 1, 'FAAC allocates federally collected revenue among federal, state and local governments.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('gov-016', 'government', 'Federalism', 'hard', 'One major argument for federalism in Nigeria is that it ___.', '["eliminates all ethnic differences","accommodates diversity and decentralises power","makes elections unnecessary","gives all power to traditional rulers"]'::jsonb, 1, 'Federalism provides a framework for managing Nigeria''s ethnic and regional diversity.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('gov-017', 'government', 'Political Parties', 'easy', 'A political party is an organised group that seeks to ___.', '["control government through elections","operate a private business","organise only cultural festivals","replace the judiciary"]'::jsonb, 0, 'Parties contest elections to win power and implement their programmes.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('gov-018', 'government', 'Political Parties', 'easy', 'The body responsible for registering political parties in Nigeria is ___.', '["INEC","NNPC","NJC","EFCC"]'::jsonb, 0, 'The Independent National Electoral Commission registers and regulates political parties.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('gov-019', 'government', 'Political Parties', 'medium', 'The first political party in Nigeria was the ___.', '["Action Group","Nigerian National Democratic Party","National Council of Nigeria and the Cameroons","Northern People''s Congress"]'::jsonb, 1, 'The NNDP was formed in 1923 by Herbert Macaulay.', 'practice', false, '2026-01-01T00:00:00.000Z'),
