  ('com-038', 'commerce', 'Finance', 'medium', 'Which financial statement shows a business''s assets, liabilities and capital at a particular date?', '["Balance sheet","Trading account","Invoice","Receipt"]'::jsonb, 0, 'A balance sheet presents assets, liabilities and capital at a specific point in time.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('com-039', 'commerce', 'Marketing', 'easy', 'Marketing is best defined as ___.', '["identifying and satisfying customer needs profitably","only advertising","only selling","storing goods"]'::jsonb, 0, 'Marketing encompasses research, product, price, promotion and distribution.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('com-040', 'commerce', 'Marketing', 'easy', 'The four Ps of marketing are product, price, place and ___.', '["promotion","people","profit","packaging"]'::jsonb, 0, 'The marketing mix comprises product, price, place and promotion.', 'practice', false, '2026-01-01T00:00:00.000Z'),
