  ('com-045', 'commerce', 'Marketing', 'medium', 'A distribution channel is the route through which goods move from ___.', '["producers to consumers","banks to government","consumers to producers","tax offices to firms"]'::jsonb, 0, 'Channels involve intermediaries that move products to final users.', 'practice', false, '2026-01-01T00:00:00.000Z'),
