  ('com-047', 'commerce', 'Marketing', 'easy', 'Market research is conducted to ___.', '["gather information about customers and markets","increase production costs","set arbitrary prices","avoid customers"]'::jsonb, 0, 'Research informs decisions about products, pricing and promotion.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('com-048', 'commerce', 'Marketing', 'medium', 'E-commerce refers to buying and selling ___.', '["over electronic networks such as the internet","only in physical shops","only through banks","only by government"]'::jsonb, 0, 'E-commerce uses digital platforms to transact.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('com-049', 'commerce', 'Marketing', 'medium', 'Sales promotion includes short-term incentives such as ___.', '["discounts and coupons","annual audits","staff recruitment","tax filing"]'::jsonb, 0, 'Promotions stimulate immediate purchases through incentives.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('com-050', 'commerce', 'Marketing', 'hard', 'A market niche is a ___ segment of a market.', '["small, specialised","very large, undifferentiated","government-owned","non-profitable by definition"]'::jsonb, 0, 'A niche is a narrowly defined group with specific needs.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('acc-001', 'accounting', 'Principles', 'easy', 'Accounting is best described as the process of ___.', '["identifying, recording and communicating financial information","selling goods only","hiring employees","manufacturing products"]'::jsonb, 0, 'Accounting records, classifies and communicates financial information to users.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('acc-002', 'accounting', 'Principles', 'medium', 'The going concern concept assumes that a business will ___.', '["continue operating for the foreseeable future","close down within a year","never make a profit","avoid all liabilities"]'::jsonb, 0, 'Financial statements are prepared on the assumption that the entity will continue in operation.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('acc-003', 'accounting', 'Principles', 'medium', 'The accrual concept recognises revenue when it is ___ and expenses when they are ___.', '["earned; incurred","received; paid","received; incurred","earned; paid"]'::jsonb, 0, 'Accrual accounting matches revenue earned with expenses incurred, regardless of cash movement.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('acc-004', 'accounting', 'Principles', 'medium', 'The consistency concept requires a business to ___.', '["apply the same accounting methods from period to period","change methods every year","ignore all standards","record only cash transactions"]'::jsonb, 0, 'Consistent methods make financial statements comparable over time.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('acc-005', 'accounting', 'Principles', 'easy', 'The business entity concept treats the owner and the business as ___.', '["separate entities","the same person","partners in law","government agencies"]'::jsonb, 0, 'Business transactions are kept separate from the owner''s personal affairs.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('acc-006', 'accounting', 'Principles', 'medium', 'Prudence in accounting means ___.', '["exercising caution when making estimates","recording only profits","overstating assets","ignoring liabilities"]'::jsonb, 0, 'Prudence avoids overstating income or assets and understating expenses or liabilities.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('acc-007', 'accounting', 'Principles', 'easy', 'The double entry principle states that every transaction has ___.', '["two aspects: a debit and a credit","one entry only","three entries","no effect on accounts"]'::jsonb, 0, 'Each transaction is recorded in at least two accounts, with debits equalling credits.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('acc-008', 'accounting', 'Principles', 'easy', 'In accounting, the left side of an account is the ___ side.', '["debit","credit","balance","capital"]'::jsonb, 0, 'Debit is conventionally the left side; credit is the right side.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('acc-009', 'accounting', 'Principles', 'medium', 'A trial balance is prepared to check the ___.', '["arithmetic accuracy of the ledger","profit for the year","market value of assets","creditworthiness of customers"]'::jsonb, 0, 'It tests whether total debits equal total credits.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('acc-010', 'accounting', 'Principles', 'easy', 'The book in which transactions are first recorded is the ___.', '["journal","ledger","trial balance","balance sheet"]'::jsonb, 0, 'The journal is the book of original entry; postings go to the ledger.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('acc-011', 'accounting', 'Double Entry', 'easy', 'An increase in an asset is recorded as a ___.', '["debit","credit","contra","liability"]'::jsonb, 0, 'Assets increase on the debit side.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('acc-012', 'accounting', 'Double Entry', 'easy', 'An increase in a liability is recorded as a ___.', '["debit","credit","expense","asset"]'::jsonb, 1, 'Liabilities and capital increase on the credit side.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('acc-013', 'accounting', 'Double Entry', 'easy', 'Capital introduced by the owner is recorded as a ___.', '["credit to capital","debit to capital","debit to sales","credit to purchases"]'::jsonb, 0, 'The business owes the owner capital, so capital is credited.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('acc-014', 'accounting', 'Double Entry', 'easy', 'An increase in an expense is recorded as a ___.', '["debit","credit","liability","income"]'::jsonb, 0, 'Expenses increase on the debit side.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('acc-015', 'accounting', 'Double Entry', 'easy', 'Revenue earned is recorded as a ___.', '["debit","credit","asset","drawing"]'::jsonb, 1, 'Income and revenue increase on the credit side.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('acc-016', 'accounting', 'Double Entry', 'medium', 'Goods bought for cash are recorded as ___.', '["debit purchases; credit cash","debit cash; credit purchases","debit sales; credit cash","debit cash; credit sales"]'::jsonb, 0, 'Purchases increase (debit) and cash decreases (credit).', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('acc-017', 'accounting', 'Double Entry', 'medium', 'Goods sold for cash are recorded as ___.', '["debit cash; credit sales","debit sales; credit cash","debit purchases; credit cash","debit capital; credit sales"]'::jsonb, 0, 'Cash increases (debit) and sales income increases (credit).', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('acc-018', 'accounting', 'Double Entry', 'medium', 'Owner''s drawings are recorded as ___.', '["debit drawings; credit cash","debit cash; credit drawings","debit capital; credit cash","debit expenses; credit sales"]'::jsonb, 0, 'Drawings reduce capital and are debited, while cash is credited.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('acc-019', 'accounting', 'Double Entry', 'medium', 'A prepaid expense is treated as a ___.', '["current asset","current liability","fixed asset","capital"]'::jsonb, 0, 'Payment made in advance represents a future benefit, hence an asset.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('acc-020', 'accounting', 'Double Entry', 'medium', 'An accrued expense is treated as a ___.', '["current liability","current asset","fixed asset","revenue"]'::jsonb, 0, 'An expense incurred but not yet paid is owed, hence a liability.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('acc-021', 'accounting', 'Final Accounts', 'easy', 'The trading account is prepared to determine ___.', '["gross profit or loss","net profit only","cash balance","capital"]'::jsonb, 0, 'The trading account matches sales with cost of goods sold to find gross profit.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('acc-022', 'accounting', 'Final Accounts', 'easy', 'The profit and loss account determines ___.', '["net profit or loss","gross profit only","stock value","bank balance"]'::jsonb, 0, 'It deducts operating expenses and adds other income to gross profit.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('acc-023', 'accounting', 'Final Accounts', 'easy', 'The balance sheet shows a business''s ___.', '["financial position at a date","profit over a period","sales only","cash receipts only"]'::jsonb, 0, 'It lists assets, liabilities and capital at a specific date.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('acc-024', 'accounting', 'Final Accounts', 'medium', 'Depreciation is the ___.', '["allocation of the cost of an asset over its useful life","increase in asset value","payment of a liability","cash purchase of stock"]'::jsonb, 0, 'Depreciation spreads an asset''s cost over its expected useful life.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('acc-025', 'accounting', 'Final Accounts', 'easy', 'Closing stock is classified as a ___.', '["current asset","current liability","fixed asset","capital"]'::jsonb, 0, 'Unsold goods at year end are a current asset.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('acc-026', 'accounting', 'Final Accounts', 'medium', 'Cost of goods sold is calculated as ___.', '["opening stock + purchases − closing stock","opening stock − purchases + closing stock","sales − expenses","closing stock + sales"]'::jsonb, 0, 'COGS = opening stock + purchases − closing stock.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('acc-027', 'accounting', 'Final Accounts', 'medium', 'If sales are ₦100,000 and cost of goods sold is ₦60,000, gross profit is ___.', '["₦40,000","₦60,000","₦160,000","₦100,000"]'::jsonb, 0, 'Gross profit = sales − cost of goods sold = 100,000 − 60,000 = ₦40,000.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('acc-028', 'accounting', 'Final Accounts', 'medium', 'If gross profit is ₦40,000 and expenses are ₦15,000, net profit is ___.', '["₦15,000","₦25,000","₦40,000","₦55,000"]'::jsonb, 1, 'Net profit = gross profit − expenses = 40,000 − 15,000 = ₦25,000.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('acc-029', 'accounting', 'Final Accounts', 'easy', 'The accounting equation is ___.', '["assets = capital + liabilities","assets = capital − liabilities","capital = assets + liabilities","liabilities = assets + capital"]'::jsonb, 0, 'Resources (assets) are financed by owners'' capital and liabilities.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('acc-030', 'accounting', 'Final Accounts', 'medium', 'A bad debt is a debt that ___.', '["is unlikely to be recovered","has been paid early","is owed to a supplier","is a fixed asset"]'::jsonb, 0, 'Bad debts are receivables that have become irrecoverable and are written off.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('acc-031', 'accounting', 'Ratios', 'easy', 'The current ratio is calculated as ___.', '["current assets ÷ current liabilities","current liabilities ÷ current assets","total assets ÷ capital","profit ÷ sales"]'::jsonb, 0, 'It measures short-term liquidity.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('acc-032', 'accounting', 'Ratios', 'medium', 'The acid test ratio excludes ___ from current assets.', '["stock","cash","debtors","bank balance"]'::jsonb, 0, 'The quick ratio removes inventory, the least liquid current asset.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('acc-033', 'accounting', 'Ratios', 'medium', 'Gross profit margin is ___.', '["gross profit ÷ sales × 100","sales ÷ gross profit × 100","net profit ÷ capital × 100","expenses ÷ sales × 100"]'::jsonb, 0, 'It expresses gross profit as a percentage of sales.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('acc-034', 'accounting', 'Ratios', 'medium', 'Net profit margin is ___.', '["net profit ÷ sales × 100","gross profit ÷ sales × 100","sales ÷ net profit × 100","assets ÷ profit × 100"]'::jsonb, 0, 'It shows how much of each naira of sales remains as net profit.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('acc-035', 'accounting', 'Ratios', 'medium', 'Return on capital employed is ___.', '["net profit ÷ capital employed × 100","sales ÷ capital × 100","gross profit ÷ expenses × 100","assets ÷ liabilities"]'::jsonb, 0, 'It measures the profit generated relative to capital invested.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('acc-036', 'accounting', 'Ratios', 'medium', 'Stock turnover is calculated as ___.', '["cost of goods sold ÷ average stock","average stock ÷ cost of goods sold","sales ÷ capital","stock ÷ debtors"]'::jsonb, 0, 'It indicates how many times stock is sold and replaced in a period.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('acc-037', 'accounting', 'Ratios', 'medium', 'The debtors'' collection period measures the average time taken to ___.', '["collect money from credit customers","pay suppliers","sell stock","pay dividends"]'::jsonb, 0, 'It estimates how long receivables remain outstanding.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('acc-038', 'accounting', 'Ratios', 'hard', 'Gearing measures the proportion of a company''s capital that is ___.', '["debt","ordinary share capital","retained earnings","fixed assets"]'::jsonb, 0, 'Gearing compares debt to total capital employed.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('acc-039', 'accounting', 'Ratios', 'medium', 'Earnings per share is calculated as ___.', '["profit after tax ÷ number of ordinary shares","dividend ÷ share price","sales ÷ assets","net profit ÷ sales"]'::jsonb, 0, 'EPS shows profit attributable to each ordinary share.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('acc-040', 'accounting', 'Ratios', 'easy', 'Working capital equals ___.', '["current assets − current liabilities","current liabilities − current assets","fixed assets + current liabilities","capital + liabilities"]'::jsonb, 0, 'It measures funds available for day-to-day operations.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('acc-041', 'accounting', 'Cost Accounting', 'easy', 'Cost accounting is mainly concerned with ___.', '["recording and controlling costs of production","preparing tax returns only","recording cash receipts","auditing banks"]'::jsonb, 0, 'It gathers cost information for planning, control and decision-making.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('acc-042', 'accounting', 'Cost Accounting', 'medium', 'Prime cost consists of ___.', '["direct materials + direct labour + direct expenses","all fixed costs","selling and distribution costs","administration expenses only"]'::jsonb, 0, 'Prime cost is the sum of direct production costs.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('acc-043', 'accounting', 'Cost Accounting', 'easy', 'Direct materials are materials that ___.', '["become part of the finished product","are used in the office","are sold as scrap only","cannot be traced to a product"]'::jsonb, 0, 'Direct materials can be identified with a specific product.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('acc-044', 'accounting', 'Cost Accounting', 'medium', 'Factory overhead includes ___.', '["indirect production costs","direct materials only","direct labour only","sales revenue"]'::jsonb, 0, 'Overheads are indirect costs such as factory rent and supervision.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('acc-045', 'accounting', 'Cost Accounting', 'easy', 'A fixed cost is one that ___.', '["does not change with output in the short run","changes directly with output","is always zero","is paid only once"]'::jsonb, 0, 'Fixed costs, like rent, remain constant over a relevant output range.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('acc-046', 'accounting', 'Cost Accounting', 'easy', 'A variable cost is one that ___.', '["varies directly with the level of output","never changes","is always a loss","is paid to shareholders"]'::jsonb, 0, 'Variable costs change in proportion to activity.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('acc-047', 'accounting', 'Cost Accounting', 'medium', 'Break-even point occurs where ___.', '["total revenue equals total cost","revenue is zero","profit is maximum","fixed cost is zero"]'::jsonb, 0, 'At break-even, there is neither profit nor loss.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('acc-048', 'accounting', 'Cost Accounting', 'medium', 'If fixed costs are ₦100,000 and contribution per unit is ₦20, the break-even quantity is ___ units.', '["2,000","5,000","10,000","20,000"]'::jsonb, 1, 'Break-even units = fixed costs ÷ contribution per unit = 100,000 ÷ 20 = 5,000.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('acc-049', 'accounting', 'Cost Accounting', 'medium', 'Marginal costing focuses on ___ costs.', '["variable","fixed","sunk","opportunity"]'::jsonb, 0, 'Marginal costing separates variable costs from fixed costs.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('acc-050', 'accounting', 'Cost Accounting', 'medium', 'Standard costing compares actual costs with ___.', '["predetermined standard costs","last year''s profit only","market prices only","share prices"]'::jsonb, 0, 'Variances between actual and standard costs guide control.', 'practice', false, '2026-01-01T00:00:00.000Z'),
