  ('agr-038', 'agricultural-science', 'Soil Science', 'medium', 'Soil conservation aims to ___.', '["prevent loss of soil fertility and erosion","increase deforestation","remove all organic matter","reduce rainfall"]'::jsonb, 0, 'Conservation practices protect soil from degradation.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('agr-039', 'agricultural-science', 'Farm Management', 'easy', 'Farm records are kept to ___.', '["monitor performance and plan decisions","entertain visitors","replace labour","increase pests"]'::jsonb, 0, 'Records track costs, yields and profits for informed management.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('agr-040', 'agricultural-science', 'Farm Management', 'medium', 'A farm budget is a plan of expected ___ and ___.', '["income; expenditure","rainfall; temperature","pests; diseases","seeds; tools only"]'::jsonb, 0, 'Budgets forecast farm revenue and costs.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('agr-041', 'agricultural-science', 'Farm Management', 'easy', 'A cooperative society helps farmers by ___.', '["pooling resources and bargaining collectively","increasing isolation","eliminating markets","preventing savings"]'::jsonb, 0, 'Cooperatives provide credit, inputs and marketing support.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('agr-042', 'agricultural-science', 'Farm Management', 'medium', 'Agricultural extension workers help farmers by ___.', '["disseminating improved practices and information","collecting all harvests","setting arbitrary prices","banning new technology"]'::jsonb, 0, 'Extension services link research to farmers.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('agr-043', 'agricultural-science', 'Farm Management', 'easy', 'Mechanisation in agriculture means using ___ to do farm work.', '["machines","only human labour","animals only","chemicals only"]'::jsonb, 0, 'Mechanisation replaces or supplements labour with machinery.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('agr-044', 'agricultural-science', 'Farm Management', 'medium', 'Agricultural marketing involves ___.', '["moving produce from farm to consumers at a profit","planting only","irrigating only","applying pesticides only"]'::jsonb, 0, 'Marketing includes storage, transport, grading and selling.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('agr-045', 'agricultural-science', 'Farm Management', 'easy', 'A major source of farm finance is ___.', '["agricultural loans and grants","lottery tickets","traffic fines","foreign passports"]'::jsonb, 0, 'Farmers obtain credit from banks, cooperatives and government schemes.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('agr-046', 'agricultural-science', 'Farm Management', 'medium', 'Labour is a ___ of production.', '["factor","product","by-product","market"]'::jsonb, 0, 'Labour is one of the factors of production, alongside land, capital and entrepreneurship.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('agr-047', 'agricultural-science', 'Farm Management', 'medium', 'Land tenure refers to the system of ___ land.', '["holding and using","irrigating","harvesting","spraying"]'::jsonb, 0, 'Land tenure defines ownership, access and use rights.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('agr-048', 'agricultural-science', 'Farm Management', 'medium', 'Farm risks include ___.', '["pests, disease and weather uncertainty","guaranteed profits","fixed prices only","constant yields"]'::jsonb, 0, 'Agriculture faces biological, climatic and market risks.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('agr-049', 'agricultural-science', 'Farm Management', 'medium', 'Agroforestry combines trees with ___.', '["crops and/or livestock","only fisheries","only buildings","only pesticides"]'::jsonb, 0, 'Agroforestry integrates trees into farming systems for multiple benefits.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('agr-050', 'agricultural-science', 'Farm Management', 'medium', 'Sustainable agriculture aims to ___.', '["meet present needs without harming future productivity","maximise deforestation","deplete all soil nutrients","ignore environmental impacts"]'::jsonb, 0, 'Sustainability balances productivity, profitability and environmental care.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('civ-001', 'civic-education', 'Rights & Duties', 'easy', 'Human rights are rights that belong to every person by virtue of being ___.', '["human","wealthy","educated","employed"]'::jsonb, 0, 'Human rights are inherent, universal and inalienable.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('civ-002', 'civic-education', 'Rights & Duties', 'easy', 'The right to life is protected by the ___.', '["constitution","traffic code","school rules","market association"]'::jsonb, 0, 'Fundamental rights, including the right to life, are guaranteed in the constitution.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('civ-003', 'civic-education', 'Rights & Duties', 'easy', 'Freedom of expression allows citizens to ___.', '["share opinions lawfully","incite violence","defame others freely","ignore all laws"]'::jsonb, 0, 'Free expression is protected within legal limits.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('civ-004', 'civic-education', 'Rights & Duties', 'medium', 'The right to fair hearing means a person accused of a crime is entitled to ___.', '["a fair and public trial","immediate punishment","secret trial without defence","trial by the police alone"]'::jsonb, 0, 'Fair hearing includes the right to defend oneself before an impartial court.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('civ-005', 'civic-education', 'Rights & Duties', 'medium', 'The Universal Declaration of Human Rights was adopted in ___.', '["1945","1948","1960","1999"]'::jsonb, 1, 'The UN General Assembly adopted the UDHR on 10 December 1948.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('civ-006', 'civic-education', 'Rights & Duties', 'easy', 'Which of the following is a civic duty of a citizen?', '["Paying taxes","Refusing to vote","Damaging public property","Avoiding school"]'::jsonb, 0, 'Citizens are expected to pay lawful taxes.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('civ-007', 'civic-education', 'Rights & Duties', 'medium', 'The right to freedom of movement allows a citizen to ___.', '["move freely within the country subject to law","enter any country without documents","trespass on private property","avoid all checkpoints"]'::jsonb, 0, 'Movement rights are guaranteed but subject to lawful restrictions.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('civ-008', 'civic-education', 'Rights & Duties', 'easy', 'Children have the right to ___.', '["education and protection","forced labour","abandonment","abuse"]'::jsonb, 0, 'The Child Rights Act protects children''s welfare and education.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('civ-009', 'civic-education', 'Rights & Duties', 'medium', 'Voting in elections is both a right and a ___.', '["responsibility","punishment","privilege for the rich","crime"]'::jsonb, 0, 'Citizens should participate responsibly in choosing leaders.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('civ-010', 'civic-education', 'Rights & Duties', 'easy', 'Public property should be ___.', '["protected and maintained","destroyed","sold illegally","ignored"]'::jsonb, 0, 'Caring for public property is a civic responsibility.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('civ-011', 'civic-education', 'Rights & Duties', 'medium', 'The National Human Rights Commission in Nigeria is responsible for ___.', '["protecting and promoting human rights","conducting elections","printing currency","building roads"]'::jsonb, 0, 'The NHRC investigates rights abuses and promotes awareness.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('civ-012', 'civic-education', 'Rights & Duties', 'hard', 'Rights are not absolute because ___.', '["their exercise must not infringe on others'' rights","only adults have rights","government can abolish all rights","rights apply only in court"]'::jsonb, 0, 'Rights are balanced against public safety and the rights of others.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('civ-013', 'civic-education', 'Rights & Duties', 'medium', 'A major duty of a citizen towards the state is ___.', '["obeying the constitution and laws","evading taxes","boycotting all elections","destroying public facilities"]'::jsonb, 0, 'Lawful obedience is fundamental to orderly society.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('civ-014', 'civic-education', 'Democracy', 'easy', 'Democracy is best defined as government by ___.', '["the people","the military","one monarch","the wealthy"]'::jsonb, 0, 'Democracy derives its authority from the consent of the governed.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('civ-015', 'civic-education', 'Democracy', 'easy', 'A key feature of democracy is ___.', '["free and fair elections","hereditary rule","one-party rule","military decrees"]'::jsonb, 0, 'Regular competitive elections are central to democracy.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('civ-016', 'civic-education', 'Democracy', 'medium', 'The principle of majority rule must be balanced with ___.', '["protection of minority rights","abolition of dissent","one-party control","censorship"]'::jsonb, 0, 'Democracies protect minorities from the tyranny of the majority.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('civ-017', 'civic-education', 'Democracy', 'medium', 'A political opposition is important in a democracy because it ___.', '["holds government accountable","prevents elections","supports dictatorship","ends debate"]'::jsonb, 0, 'Opposition parties scrutinise government and offer alternatives.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('civ-018', 'civic-education', 'Democracy', 'easy', 'A constitution performs the function of ___.', '["defining and limiting government power","enriching leaders","eliminating courts","cancelling elections"]'::jsonb, 0, 'Constitutions establish institutions and limits on power.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('civ-019', 'civic-education', 'Democracy', 'medium', 'Separation of powers divides government into ___.', '["executive, legislature and judiciary","federal, state and local","rich, poor and middle class","army, police and customs"]'::jsonb, 0, 'The three branches check and balance one another.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('civ-020', 'civic-education', 'Democracy', 'easy', 'Suffrage is the right to ___.', '["vote","own land","travel abroad","free education"]'::jsonb, 0, 'Suffrage is the right to vote in elections.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('civ-021', 'civic-education', 'Democracy', 'medium', 'Political participation includes all of the following EXCEPT ___.', '["voting","joining a political party","peaceful protest","boycotting all civic duties permanently"]'::jsonb, 3, 'Democracy depends on participation; permanently rejecting civic duties undermines it.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('civ-022', 'civic-education', 'Democracy', 'medium', 'Civil society organisations contribute to democracy by ___.', '["advocating public interests and monitoring power","controlling the army","abolishing elections","appointing judges"]'::jsonb, 0, 'CSOs promote accountability, rights and civic engagement.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('civ-023', 'civic-education', 'Democracy', 'medium', 'A free press is important in a democracy because it ___.', '["informs citizens and scrutinises government","supports only one party","spreads only rumours","replaces the judiciary"]'::jsonb, 0, 'Independent media support informed public debate.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('civ-024', 'civic-education', 'Democracy', 'medium', 'A referendum is a direct vote by citizens on a ___ issue.', '["specific public","court","military","private company"]'::jsonb, 0, 'Referendums allow voters to decide a particular question directly.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('civ-025', 'civic-education', 'Democracy', 'hard', 'Accountability in a democracy means that public officials ___.', '["must answer for their actions and use of power","are above the law","cannot be criticised","serve for life"]'::jsonb, 0, 'Accountability ensures power is exercised responsibly.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('civ-026', 'civic-education', 'Democracy', 'easy', 'A democratic election should be conducted by ___.', '["an independent electoral body","the ruling party","the military","the opposition party"]'::jsonb, 0, 'An impartial electoral commission builds public trust in results.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('civ-027', 'civic-education', 'Rule of Law', 'easy', 'The rule of law means that ___.', '["everyone is subject to the law","leaders are above the law","only judges must obey laws","custom overrides law"]'::jsonb, 0, 'No one, including government officials, is above the law.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('civ-028', 'civic-education', 'Rule of Law', 'easy', 'Equality before the law means that ___.', '["all persons are subject to the same legal standards","the rich receive lighter sentences","leaders cannot be tried","only citizens can sue"]'::jsonb, 0, 'The law applies equally regardless of status or wealth.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('civ-029', 'civic-education', 'Rule of Law', 'medium', 'Due process requires that a person cannot be punished without ___.', '["a fair legal procedure","a presidential order","public opinion","media trial"]'::jsonb, 0, 'Due process protects individuals from arbitrary state action.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('civ-030', 'civic-education', 'Rule of Law', 'medium', 'An independent judiciary is essential because courts must ___.', '["decide cases without political interference","follow government instructions","favour the ruling party","avoid interpreting laws"]'::jsonb, 0, 'Judicial independence safeguards fairness and rights.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('civ-031', 'civic-education', 'Rule of Law', 'hard', 'Habeas corpus protects a person against ___.', '["unlawful detention","taxation","eviction","defamation"]'::jsonb, 0, 'Habeas corpus requires authorities to justify detention before a court.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('civ-032', 'civic-education', 'Rule of Law', 'easy', 'The presumption of innocence means an accused person is ___.', '["innocent until proven guilty","guilty until proven innocent","always released","never tried"]'::jsonb, 0, 'The burden of proof lies on the prosecution.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('civ-033', 'civic-education', 'Rule of Law', 'medium', 'The right to appeal allows a convicted person to ___.', '["ask a higher court to review the decision","avoid all punishment automatically","choose the judge","ignore the law"]'::jsonb, 0, 'Appeals provide a check against judicial error.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('civ-034', 'civic-education', 'Rule of Law', 'easy', 'Constitutional supremacy means that any law inconsistent with the constitution is ___.', '["void to the extent of the inconsistency","automatically valid","superior to the constitution","left to the army"]'::jsonb, 0, 'The constitution is the supreme law; inconsistent provisions are invalid.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('civ-035', 'civic-education', 'Rule of Law', 'medium', 'Legal aid provides ___ to those who cannot afford it.', '["legal representation and advice","free land","employment","political office"]'::jsonb, 0, 'Legal aid promotes access to justice for indigent citizens.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('civ-036', 'civic-education', 'Rule of Law', 'medium', 'A fair trial includes ___.', '["an impartial court and the right to defend oneself","secret evidence only","trial without a judge","denial of counsel"]'::jsonb, 0, 'Fair procedures are essential to justice.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('civ-037', 'civic-education', 'Rule of Law', 'medium', 'Arbitrary arrest is a violation of ___.', '["personal liberty","free trade","property ownership only","academic freedom only"]'::jsonb, 0, 'Arrests must have legal basis and follow due process.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('civ-038', 'civic-education', 'Rule of Law', 'easy', 'The law should be applied ___.', '["consistently and impartially","according to the wealth of parties","only during elections","to punish opponents"]'::jsonb, 0, 'Consistent, impartial application is central to the rule of law.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('civ-039', 'civic-education', 'National Values', 'easy', 'Integrity means ___.', '["being honest and having strong moral principles","accumulating wealth at any cost","avoiding responsibility","pretending to be loyal"]'::jsonb, 0, 'Integrity is consistency between values, words and actions.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('civ-040', 'civic-education', 'National Values', 'easy', 'Honesty is important because it ___.', '["builds trust","destroys relationships","encourages corruption","weakens institutions"]'::jsonb, 0, 'Honesty underpins trust in personal and public life.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('civ-041', 'civic-education', 'National Values', 'medium', 'Discipline involves ___.', '["self-control and obedience to lawful rules","doing whatever one likes","ignoring authority","wasting resources"]'::jsonb, 0, 'Discipline supports order, responsibility and achievement.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('civ-042', 'civic-education', 'National Values', 'easy', 'Patriotism is love and loyalty towards one''s ___.', '["country","school only","football club","employer"]'::jsonb, 0, 'Patriots show commitment to their nation''s wellbeing.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('civ-043', 'civic-education', 'National Values', 'medium', 'Nationalism in Nigeria can be promoted by ___.', '["respecting national symbols and contributing to development","ethnic discrimination","vandalising public property","refusing to pay taxes"]'::jsonb, 0, 'Shared commitment to the nation strengthens unity.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('civ-044', 'civic-education', 'National Values', 'medium', 'National unity in Nigeria is best promoted by ___.', '["tolerance and equal treatment of all groups","ethnic segregation","religious conflict","regional discrimination"]'::jsonb, 0, 'Fairness and tolerance build cohesion in a diverse society.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('civ-045', 'civic-education', 'National Values', 'easy', 'Tolerance means ___.', '["accepting differences respectfully","agreeing with everyone always","ignoring injustice","hiding one''s views"]'::jsonb, 0, 'Tolerance respects diversity while maintaining lawful boundaries.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('civ-046', 'civic-education', 'National Values', 'medium', 'Hard work is a national value because it ___.', '["promotes productivity and self-reliance","encourages laziness","guarantees wealth without effort","replaces education"]'::jsonb, 0, 'Diligence drives personal and national development.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('civ-047', 'civic-education', 'National Values', 'easy', 'Self-reliance means ___.', '["using one''s own efforts and resources","depending entirely on others","begging for everything","avoiding work"]'::jsonb, 0, 'Self-reliance emphasises initiative and responsible independence.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('civ-048', 'civic-education', 'National Values', 'medium', 'Corruption is harmful because it ___.', '["undermines trust, fairness and development","increases efficiency","strengthens institutions","reduces poverty automatically"]'::jsonb, 0, 'Corruption diverts resources and weakens public institutions.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('civ-049', 'civic-education', 'National Values', 'medium', 'Nigerian national symbols include the flag, anthem and ___.', '["coat of arms","school uniform","market logo","private company badge"]'::jsonb, 0, 'The coat of arms is an official national symbol.', 'practice', false, '2026-01-01T00:00:00.000Z'),
  ('civ-050', 'civic-education', 'National Values', 'hard', 'Good citizenship requires a balance between rights and ___.', '["responsibilities","privileges","wealth","entertainment"]'::jsonb, 0, 'Rights carry corresponding duties and responsibilities.', 'practice', false, '2026-01-01T00:00:00.000Z')
